// V30: curriculum overrides are scoped by education type AND stage/grade.
// Default subjects remain in code; their edits live as separate override nodes.
const subjectList=(s=state.stage,g=state.grade,t=state.type,opts={})=>{
 const base=(t==='azhar'?subjectsAzhar:subjectsBase)[s]||[];
 const result=base.map(([id,name,img],i)=>({id,name,img,order:(i+1)*10,isDefault:true,isHidden:false,storageKey:''}));
 const extra=val(state.public.customSubjects?.[s]?.[g]);
 const entries=Object.entries(extra).filter(([,o])=>o&&typeof o==='object'&&(!o.type||o.type===t));
 // Legacy overrides run first; new namespaced overrides take priority.
 entries.sort(([a],[b])=>Number(a.startsWith(t+'__'))-Number(b.startsWith(t+'__')));
 for(const [key,o] of entries){
  const id=String(o.id||key);const i=result.findIndex(x=>x.id===id);
  const defaults=i>=0?result[i]:{id,name:id,img:'books.png',order:(result.length+1)*10,isDefault:false,isHidden:false,storageKey:''};
  const order=Number(o.order);
  const row={...defaults,name:String(o.name||defaults.name),imageUrl:String(o.imageUrl||''),isHidden:o.isHidden===true,order:Number.isFinite(order)&&order>=0?order:defaults.order,storageKey:key};
  if(i>=0)result[i]=row;else result.push(row);
 }
 return result.filter(x=>opts.includeHidden||x.isHidden!==true).sort((a,b)=>a.order-b.order||a.name.localeCompare(b.name,'ar'));
};
