// V30 stage 2: unit labels/cover/order are metadata, lessons keep their original IDs.
// Store under publicly readable settings so the existing PHP ACL needs no migration.
function v30Units(type,stage,grade,subject,lessons=[]){
 const saved=val(state.public.settings?.curriculumUnits?.[type]?.[stage]?.[String(grade)]?.[subject]);
 const ids=new Set([...Object.keys(saved),...lessons.map(l=>String(Number(l.unit)||1))]);
 return [...ids].filter(id=>/^[1-9]\d{0,1}$/.test(id)).map(id=>{
  const row=val(saved[id]),order=Number(row.order);
  return {id,number:Number(id),name:String(row.name||'الوحدة '+id),imageUrl:safeURL(row.imageUrl||''),isHidden:row.isHidden===true,
    order:Number.isFinite(order)&&order>=0?order:Number(id)*10,hasCustom:!!Object.keys(row).length};
 }).sort((a,b)=>a.order-b.order||a.number-b.number);
}
function v30UnitPath(type,stage,grade,subject,unit){return `settings/curriculumUnits/${type}/${stage}/${grade}/${subject}/${unit}`;}
function v30LessonComparator(type,stage,grade,subject){
 const units=v30Units(type,stage,grade,subject),rank=new Map(units.map((x,i)=>[x.number,i]));
 return (a,b)=>(rank.get(Number(a.unit)||1)??999)-(rank.get(Number(b.unit)||1)??999)||
   Number(a.order??0)-Number(b.order??0)||Number(a.createdAt||0)-Number(b.createdAt||0)||String(a.id).localeCompare(String(b.id));
}
const scopedLessons=()=>{
 const t=state.type,s=state.stage,g=state.grade,subject=state.subject;
 const list=allLessons().filter(l=>(l.type||'public')===t&&l.stage===s&&String(l.grade)===String(g)&&l.subject===subject);
 const hidden=new Set(v30Units(t,s,g,subject,list).filter(u=>u.isHidden).map(u=>u.number));
 return list.filter(l=>!hidden.has(Number(l.unit)||1)).sort(v30LessonComparator(t,s,g,subject));
};
