// V29: the original database stores approved lesson questions inside lessons/<id>/questions.
// Keep that older format readable instead of forcing users to recreate their quizzes.
function embeddedLessonQuestions(lesson){
 if(!lesson||lesson.accessLocked)return [];
 const raw=lesson.questions;
 const items=Array.isArray(raw)?raw:Object.values(val(raw));
 return items.filter(q=>q&&typeof q==='object').map(normalizeQuestion).filter(x=>x.question&&x.options.length>=2&&x.correct>=0&&x.correct<x.options.length);
}
function getMasteryRows(mastery){
 const out=[];
 for(const [type,stages] of Object.entries(val(mastery)))for(const [stage,grades] of Object.entries(val(stages)))for(const [grade,subjects] of Object.entries(val(grades)))for(const [subject,lessons] of Object.entries(val(subjects)))for(const [key,entry] of Object.entries(val(lessons))){
   if(!entry||typeof entry!=='object'||Array.isArray(entry))continue;
   const status=String(entry.status||'not_started');
   out.push({lessonId:String(entry.lessonId||key),type,stage,grade,subject,status,updatedAt:Number(entry.updatedAt||0)});
 }
 return out;
}
function learningSummary(profile,mastery){
 const old=getMasteryRows(mastery).filter(x=>x.status!=='not_started');
 const newProgress=Object.entries(val(profile?.learningProgress)).filter(([,v])=>v?.completed===true).map(([id])=>id);
 const ids=new Set([...old.filter(x=>['completed','mastered','done'].includes(x.status)).map(x=>x.lessonId),...newProgress]);
 return {completed:ids.size,active:old.filter(x=>!['completed','mastered','done'].includes(x.status)).length};
}

