const siteCover=(key,fallback)=>safeURL(siteSettings()[key]||'')||fallback;
const siteMark=()=>siteLogo()?`<img class="v28-brand-logo" src="${E(siteLogo())}" alt="شعار الأكاديمية">`:'🎓';
const title=(t,sub='',action='')=>`<div class="v22-top"><div><span class="v22-kicker">${E(siteName())} • ${E(v30Slogan())}</span><h1>${E(t)}</h1>${sub?`<p>${E(sub)}</p>`:''}</div>${action}</div>`;
const B=(label,act,cls='v22-primary',extra='')=>`<button type="button" class="v22-btn ${cls}" data-action="${E(act)}" ${extra}>${label}</button>`;
const empty=(head,body)=>`<div class="v22-empty"><strong>${E(head)}</strong><p>${E(body)}</p></div>`;
const showtoast=(m)=>{document.querySelector('.v22-toast')?.remove();const div=document.createElement('div');div.className='v22-toast';div.setAttribute('role','status');div.textContent=m;document.body.append(div);setTimeout(()=>div.remove(),3700)};
const safeURL=(u)=>{if(!String(u??'').trim())return'';try{let x=new URL(u,location.href);return ['https:','http:'].includes(x.protocol)?x.href:''}catch{return''}};
// V30 phase 4 — unified brand/footer/social presence in V20 without affecting navigation or account roles.
const v30Brand=()=>val(siteSettings().appearanceBrand);
const v30Slogan=()=>String(v30Brand().tagline||'كل خطوة تصنع فارقًا');
const v30Footer=()=>String(v30Brand().footerText||'موقع تعليمي متصل بالنظام الحقيقي');
const v30SocialPlatforms=[['whatsapp','واتساب','◉'],['facebook','فيسبوك','f'],['telegram','تليجرام','➤'],['youtube','يوتيوب','▶'],['tiktok','تيك توك','♪']];
/* V52 UI: data-driven presentation only. No code/template injection, no student grades or auth mutations. */
const V52_DEFAULTS=Object.freeze({preset:'v20',defaultMode:'light',primaryColor:'#315cf4',accentColor:'#7055ed',cards:'soft',socialPlacement:'all',socialAlign:'center',socialOrder:['whatsapp','facebook','telegram','youtube','tiktok'],motion:true,revision:0});
const V52_PRESETS=Object.freeze([['v20','الأصلي V20','الواجهة الأصلية بدون تغيير'],['academic','أكاديمي','ألوان زرقاء هادئة'],['modern','حديث','تباين وبطاقات معاصرة'],['minimal','بسيط','مساحات نظيفة وزخارف أقل'],['vivid','حيوي','ألوان لامعة وتفاعل واضح'],['rose','وردي','درجات وردية لطيفة'],['night','ليلي','هوية داكنة متكاملة']]);
const v52={preview:null,error:'',order:null};
function v52PrefRead(){try{const x=localStorage.getItem('egtaz-v52-color-mode');return x==='dark'||x==='light'?x:null}catch{return null}}
function v52PrefWrite(mode){try{if(mode===null)localStorage.removeItem('egtaz-v52-color-mode');else localStorage.setItem('egtaz-v52-color-mode',mode)}catch{}}
let v52UserMode=v52PrefRead();
function v52Config(){const saved=val(siteSettings().appearanceV52);return {...V52_DEFAULTS,...saved,socialOrder:Array.isArray(saved.socialOrder)?saved.socialOrder:V52_DEFAULTS.socialOrder}}
function v52ConfigChecked(raw){const c={...V52_DEFAULTS,...raw};const validPreset=V52_PRESETS.some(x=>x[0]===c.preset);c.preset=validPreset?c.preset:'v20';c.defaultMode=['light','dark'].includes(c.defaultMode)?c.defaultMode:'light';c.cards=['soft','flat','glass'].includes(c.cards)?c.cards:'soft';c.socialPlacement=['all','header','footer','sidebar','hidden'].includes(c.socialPlacement)?c.socialPlacement:'all';c.socialAlign=['start','center','end'].includes(c.socialAlign)?c.socialAlign:'center';c.socialOrder=Array.isArray(c.socialOrder)&&c.socialOrder.length===5&&new Set(c.socialOrder).size===5&&c.socialOrder.every(x=>v30SocialPlatforms.some(p=>p[0]===x))?c.socialOrder:V52_DEFAULTS.socialOrder;c.motion=c.motion!==false;for(const key of ['primaryColor','accentColor'])c[key]=/^#[0-9a-f]{6}$/i.test(c[key]||'')?c[key]:V52_DEFAULTS[key];return c;}
function v52Apply(){const c=v52ConfigChecked(v52.preview||v52Config());const mode=v52UserMode||c.defaultMode;document.body.dataset.v52Mode=mode;document.body.dataset.v52Preset=c.preset;document.body.dataset.v52Cards=c.cards;document.body.dataset.v52Motion=c.motion?'on':'off';document.body.dataset.v52SocialAlign=c.socialAlign;document.body.dataset.theme=c.preset==='v20'?'violet':c.preset;document.body.dataset.round='round';document.documentElement.style.colorScheme=mode;
 for(const [key,css]of [['primaryColor','--v52-primary'],['accentColor','--v52-accent']])document.body.style.setProperty(css,c[key]);
 document.documentElement.dataset.v52Mode=mode;
 // Synchronize button labels without a full rerender (preserves form input and sidebar scroll).
 document.querySelectorAll('[data-action="v52-toggle"]').forEach(btn=>{btn.textContent=mode==='dark'?'☀️ نهاري':'🌙 ليلي';btn.setAttribute('aria-label',mode==='dark'?'تشغيل الوضع النهاري':'تشغيل الوضع الليلي');btn.setAttribute('aria-pressed',String(mode==='dark'))});
}
function v52ToggleButton(extra=''){const mode=v52UserMode||v52ConfigChecked(v52.preview||v52Config()).defaultMode;return `<button type="button" class="v52-toggle" data-action="v52-toggle" aria-label="${mode==='dark'?'تشغيل الوضع النهاري':'تشغيل الوضع الليلي'}" aria-pressed="${mode==='dark'}" ${extra}>${mode==='dark'?'☀️ نهاري':'🌙 ليلي'}</button>`}
function v52SocialMarkup(order){return order.map((id,index)=>{const platform=v30SocialPlatforms.find(p=>p[0]===id),label=platform?.[1]||id;return `<div class="v52-social-item" data-v52-social="${E(id)}"><span><b>${E(label)}</b><small>المركز ${index+1}</small></span><div>${B('↑','v52-social-move','v22-secondary',`data-id="${id}" data-step="-1" aria-label="رفع ${E(label)}" ${index===0?'disabled':''}`)}${B('↓','v52-social-move','v22-secondary',`data-id="${id}" data-step="1" aria-label="خفض ${E(label)}" ${index===order.length-1?'disabled':''}`)}</div></div>`}).join('')}
function v52AdminUI(){const c=v52ConfigChecked(v52.preview||v52Config());const rev=Number(v52Config().revision)||0;return `${title('قوالب وتصميم الأكاديمية V52','تحكم عام في الألوان والبطاقات وأماكن الحسابات الاجتماعية مع إبقاء تصميم V20 الأصلي متاحًا.')}<section class="v22-card v52-intro"><h3>التخصيص المباشر</h3><p>القالب العام يراه جميع الزوار والمستخدمين؛ يستطيع كل مستخدم اختيار النهاري أو الليلي لنفسه فقط. المعاينة لا تُنشر إلا بعد حفظها.</p><div class="v22-btnrow">${B('معاينة التصميم الأصلي V20','v52-original','v22-secondary')}${B('إلغاء المعاينة','v52-cancel','v22-secondary')}${B('اتباع الإعداد العام للوضع','v52-reset-mode','v22-secondary')}</div>${v52.error?`<p role="alert" class="v52-error">${E(v52.error)}</p>`:''}</section><form id="v52-design-form" class="v52-form"><input type="hidden" name="revision" value="${rev}"><section class="v22-card"><h3>1. اختر أحد قوالب التصميم السبعة</h3><div class="v52-preset-grid">${V52_PRESETS.map(([id,label,desc])=>`<label class="v52-preset ${c.preset===id?'selected':''}" data-preset="${id}"><input type="radio" name="preset" value="${id}" ${c.preset===id?'checked':''}><span class="v52-preset-preview v52-preview-${id}"><i></i><i></i><i></i></span><strong>${E(label)}</strong><small>${E(desc)}</small></label>`).join('')}</div></section><section class="v22-card"><h3>2. الألوان والمظهر والبطاقات</h3><div class="v52-controls"><label>الوضع الافتراضي للموقع<select name="defaultMode"><option value="light" ${c.defaultMode==='light'?'selected':''}>نهاري</option><option value="dark" ${c.defaultMode==='dark'?'selected':''}>ليلي</option></select></label><label>اللون الأساسي<input type="color" name="primaryColor" value="${E(c.primaryColor)}"></label><label>لون العناصر البارزة<input type="color" name="accentColor" value="${E(c.accentColor)}"></label><label>شكل البطاقات<select name="cards"><option value="soft" ${c.cards==='soft'?'selected':''}>ظلال ناعمة</option><option value="flat" ${c.cards==='flat'?'selected':''}>بسيط ومسطح</option><option value="glass" ${c.cards==='glass'?'selected':''}>زجاجي</option></select></label></div><label class="v52-check"><input type="checkbox" name="motion" ${c.motion?'checked':''}> تفعيل الحركات الخفيفة (تتوقف تلقائيًا عند تفضيل تقليل الحركة)</label><div class="v52-live-sample"><div class="v52-sample-card"><strong>نموذج بطاقة مادة</strong><p>مثال للبطاقات والأزرار الرئيسية قبل النشر.</p><button type="button" class="v22-btn v22-primary">ابدأ التعلم</button></div></div></section><section class="v22-card"><h3>3. الأيقونات والحسابات الاجتماعية</h3><p>تتحكم هنا في أماكن ظهور الروابط وترتيبها. وتُعدّل الروابط نفسها من صفحة «الصور وترتيب الرئيسية» القديمة.</p><div class="v52-controls"><label>مكان الأيقونات<select name="socialPlacement"><option value="all" ${c.socialPlacement==='all'?'selected':''}>الرأس والتذييل والقائمة</option><option value="header" ${c.socialPlacement==='header'?'selected':''}>أعلى الصفحة فقط</option><option value="footer" ${c.socialPlacement==='footer'?'selected':''}>أسفل الصفحة فقط</option><option value="sidebar" ${c.socialPlacement==='sidebar'?'selected':''}>القائمة الجانبية فقط</option><option value="hidden" ${c.socialPlacement==='hidden'?'selected':''}>إخفاء الأيقونات</option></select></label><label>محاذاة الأيقونات<select name="socialAlign"><option value="start" ${c.socialAlign==='start'?'selected':''}>البداية</option><option value="center" ${c.socialAlign==='center'?'selected':''}>الوسط</option><option value="end" ${c.socialAlign==='end'?'selected':''}>النهاية</option></select></label></div><input type="hidden" name="socialOrder" value="${E(c.socialOrder.join(','))}"><div id="v52-social-sort">${v52SocialMarkup(c.socialOrder)}</div><div class="v22-btnrow">${B('تعديل روابط التواصل','route','v22-secondary','data-view="appearance"')}</div></section><div class="v52-save"><button type="submit" class="v22-btn v22-primary">حفظ وتطبيق القالب على الأكاديمية</button><small>النسخة ${rev} — حفظ المدير فقط؛ لا يُعدل محتوى الدروس أو الاختبارات.</small></div></form>`}
function v52DraftFromForm(form){const fd=new FormData(form);return {preset:String(fd.get('preset')||'v20'),defaultMode:String(fd.get('defaultMode')||'light'),primaryColor:String(fd.get('primaryColor')||''),accentColor:String(fd.get('accentColor')||''),cards:String(fd.get('cards')||'soft'),socialPlacement:String(fd.get('socialPlacement')||'all'),socialAlign:String(fd.get('socialAlign')||'center'),socialOrder:String(fd.get('socialOrder')||'').split(','),motion:fd.has('motion'),revision:Number(fd.get('revision'))||0}}
function v52Preview(form){v52.preview=v52ConfigChecked(v52DraftFromForm(form));v52Apply();form.querySelectorAll('.v52-preset').forEach(p=>p.classList.toggle('selected',p.dataset.preset===v52.preview.preset));}
async function v52Submit(form){if(ROLE!=='admin')throw Error('ليس لديك صلاحية');const data=v52DraftFromForm(form);const result=await post('v52/admin/design',data);state.public.settings.appearanceV52=result.design;v52.preview=null;v52.error='';showtoast('تم نشر مظهر الأكاديمية بنجاح');v52Apply();render();}
function v52Click(el){const action=el.dataset.action;if(action==='v52-toggle'){v52UserMode=(v52UserMode||v52ConfigChecked(v52.preview||v52Config()).defaultMode)==='dark'?'light':'dark';v52PrefWrite(v52UserMode);v52Apply();return}
 if(action==='v52-reset-mode'){v52UserMode=null;v52PrefWrite(null);v52Apply();showtoast('الوضع الآن يتبع اختيار الإدارة');return}
 if(action==='v52-cancel'){v52.preview=null;v52.error='';v52Apply();render();return}
 if(action==='v52-original'){v52.preview={...V52_DEFAULTS,...v52Config(),preset:'v20',cards:'soft',defaultMode:'light'};v52Apply();render();showtoast('معاينة V20 فقط — اضغط حفظ لاعتمادها على الموقع');return}
 if(action==='v52-social-move'){const form=el.closest('form');if(!form)return;const field=form.elements.socialOrder,items=String(field.value||'').split(',');const at=items.indexOf(el.dataset.id),dest=at+Number(el.dataset.step);if(at<0||dest<0||dest>=items.length)return;[items[at],items[dest]]=[items[dest],items[at]];field.value=items.join(',');form.querySelector('#v52-social-sort').innerHTML=v52SocialMarkup(items);v52Preview(form);return}}

const v30HttpsURL=(value)=>{try{const s=String(value||'').trim();if(!s)return'';const url=new URL(s);return url.protocol==='https:'&&url.hostname?url.href:''}catch{return''}};
function v30SocialRow(compact=false,slot='footer'){
 const theme=v52ConfigChecked(v52.preview||v52Config());if(v30Brand().hideSocialLinks===true||theme.socialPlacement==='hidden'||(theme.socialPlacement!=='all'&&theme.socialPlacement!==slot))return'';
 const saved=val(siteSettings().socialLinks);
 const links=theme.socialOrder.map(id=>v30SocialPlatforms.find(p=>p[0]===id)).filter(Boolean).map(([id,label,icon])=>{
  const candidate=saved[id]||(id==='whatsapp'?siteSettings().whatsapp:'');
  const url=v30HttpsURL(candidate);
  return url?`<a class="v30-social-link" href="${E(url)}" target="_blank" rel="noopener noreferrer" aria-label="${E(label)}" title="${E(label)}"><span aria-hidden="true">${E(icon)}</span>${compact?'':`<span>${E(label)}</span>`}</a>`:'';
 }).filter(Boolean);
 return links.length?`<nav class="v30-social-row ${compact?'is-compact':''}" aria-label="حسابات الأكاديمية الرسمية">${links.join('')}</nav>`:'';
}

const embedYoutube=u=>{const safe=safeURL(u);if(!safe)return'';try{const x=new URL(safe),host=x.hostname.toLowerCase().replace(/^www\.|^m\./,'');if(!['youtube.com','youtube-nocookie.com','youtu.be'].includes(host))return'';const segments=x.pathname.split('/').filter(Boolean);let id=host==='youtu.be'?segments[0]:x.searchParams.get('v')||(['shorts','embed','live','v'].includes(segments[0])?segments[1]:'');return /^[A-Za-z0-9_-]{11}$/.test(id||'')?`https://www.youtube-nocookie.com/embed/${id}`:''}catch{return''}};
const cleanHtml=text=>{const d=document.createElement('div');d.textContent=String(text??'');return d.innerHTML.replace(/\n/g,'<br>')};

const richContent=(raw,format='')=>{
 const original=String(raw??'').trim();if(!original)return'<p class="v23-no-content">لم يُضف شرح مكتوب بعد.</p>';
 const isHtml=format==='html'||(/<(?:p|div|br|h[1-6]|ul|ol|li|strong|b|table|blockquote|span|img)\b/i).test(original);
 if(!isHtml)return'<p>'+E(original).replace(/\r?\n/g,'<br>')+'</p>';
 const source=document.createElement('template');source.innerHTML=original;
 const allowed=new Set(['P','DIV','BR','H1','H2','H3','H4','H5','H6','UL','OL','LI','STRONG','B','I','EM','U','BLOCKQUOTE','TABLE','THEAD','TBODY','TR','TD','TH','A','IMG','HR','CODE','PRE','SPAN','SUP','SUB']);
 const discard=new Set(['SCRIPT','STYLE','SVG','IFRAME','OBJECT','EMBED','FORM','INPUT','BUTTON','VIDEO','AUDIO','META','LINK']);
 const walk=(node,depth=0)=>{if(depth>28)return'';if(node.nodeType===3)return E(node.textContent);if(node.nodeType!==1)return'';const tag=node.tagName;if(discard.has(tag))return'';
 const children=Array.from(node.childNodes).map(n=>walk(n,depth+1)).join('');if(!allowed.has(tag))return children;
 if(tag==='BR'||tag==='HR')return'<'+tag.toLowerCase()+'>';
 if(tag==='IMG'){const src=safeURL(node.getAttribute('src'));return src?'<img loading="lazy" src="'+E(src)+'" alt="'+E(node.getAttribute('alt')||'صورة توضيحية')+'">':''}
 if(tag==='A'){const href=safeURL(node.getAttribute('href'));return href?'<a target="_blank" rel="noopener noreferrer" href="'+E(href)+'">'+children+'</a>':children}
 return'<'+tag.toLowerCase()+'>'+children+'</'+tag.toLowerCase()+'>';
 };
 const result=Array.from(source.content.childNodes).map(n=>walk(n)).join('');return result||'<p>'+E(source.content.textContent||'')+'</p>';
};
const lessonVideos=(row)=>{const candidates=Array.isArray(row?.videos)?row.videos:Object.values(val(row?.videos));const result=candidates.map(v=>typeof v==='string'?{url:v,title:'فيديو الدرس'}:v).filter(v=>v&&safeURL(v.url||v.videoUrl));const direct=row?.videoUrl||row?.youtubeUrl||row?.videoLink;if(direct&&safeURL(direct))result.push({url:direct,title:'فيديو الدرس'});return result};
const videoPlayer=(video)=>{if(!video)return `<div class="v23-video-empty"><img src="${pic('books.png')}" alt=""><strong>لم يُضف فيديو لهذا الدرس بعد</strong><small>يمكن للإدارة إضافة فيديو من «تعديل الدرس».</small></div>`;
 const url=safeURL(video.url||video.videoUrl),embed=embedYoutube(url);if(embed)return`<iframe src="${E(embed)}" loading="lazy" referrerpolicy="strict-origin-when-cross-origin" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen title="${E(video.title||'فيديو شرح الدرس')}"></iframe>`;
 if(/\.(?:mp4|webm|ogg)(?:[?#]|$)/i.test(url))return`<video controls playsinline preload="metadata" src="${E(url)}"></video>`;
 return `<div class="v23-video-empty"><span style="font-size:48px">▶</span><strong>الفيديو متاح على موقع خارجي</strong><a class="v22-btn v22-primary" href="${E(url)}" target="_blank" rel="noopener noreferrer">فتح الفيديو ↗</a></div>`;
};

const fields={type:`<label>نوع التعليم<select name="type"><option value="public">التربية والتعليم</option><option value="azhar">الأزهر</option></select></label>`,stage:`<label>المرحلة<select name="stage"><option value="primary">ابتدائي</option><option value="prep">إعدادي</option><option value="sec">ثانوي</option></select></label>`,grade:`<label>رقم الصف<select name="grade">${[1,2,3,4,5,6].map(n=>`<option value="${n}">${n}</option>`).join('')}</select></label>`,subject:`<label>المادة<select name="subject">${[...new Map(Object.values(subjectsBase).flat().map(([id,name])=>[id,name])).entries()].map(([id,name])=>`<option value="${E(id)}">${E(name)}</option>`).join('')}</select></label>`};
function header(){const u=state.user;const links=ROLE==='student'?[['الرئيسية',''],['المراحل التعليمية','stages'],['المواد الدراسية','subjects'],['المعلمون','teachers'],['مكتبتي','library']]:[['الرئيسية','home']];return `<header class="launch-header"><div class="launch-head-inner"><a class="launch-brand" href="index.html"><span class="launch-brand-mark">${siteMark()}</span><span><strong>${E(siteName())}</strong><small>${E(v30Slogan())}</small></span></a><nav class="launch-menu" aria-label="القائمة الرئيسية">${links.map(([n,v])=>`<a href="${E(W({view:v}))}">${n}</a>`).join('')}</nav><div class="launch-head-actions">${v52ToggleButton()}${u?`<span class="v22-chip">${E(ROLE==='student'?(state.profile?.name||u.displayName||'مرحبًا'):(u.displayName||'مرحبًا'))}</span>${B('تحديث البيانات','v28-sync','v22-secondary')}${B('خروج','logout','v22-secondary')}`:B('تسجيل الدخول','login','v22-secondary v41-header-signin')+`<a class="v22-btn v41-header-parent" href="parent.html" aria-label="دخول ولي الأمر"><span class="v41-parent-full">دخول ولي الأمر</span><span class="v41-parent-short">ولي الأمر</span></a><a class="v22-btn v22-primary v41-register" href="index.html?view=register">ابدأ رحلتك ←</a>`}${v30SocialRow(true,'header')}</div></div></header>`}

