const v44={selected:'about',pages:null,loading:false,error:''};
const V44_LABELS={about:'من نحن',privacy:'سياسة الخصوصية',terms:'شروط الاستخدام'};
function v44FooterLinks(side=false){return `<nav class="${side?'v44-side-links':'v44-footer-links'}" aria-label="الصفحات الأساسية"><a href="./about.html">من نحن</a><a href="./privacy.html">سياسة الخصوصية</a><a href="./terms.html">شروط الاستخدام</a></nav>`;}
function v44PagesAdminUI(){
 const p=v44.pages?.[v44.selected],slug=v44.selected;
 return `<section class="v22-card v44-edit-card"><div class="v44-editor-head"><h2>إدارة الصفحات الأساسية</h2><p>عدّل محتوى صفحات الموقع وانشره بعد المراجعة. تُعرض الصفحات للزوار دون تسجيل دخول.</p></div><div class="v44-admin-tabs" role="group" aria-label="اختر الصفحة">${Object.entries(V44_LABELS).map(([id,name])=>`<button type="button" class="v44-admin-tab ${slug===id?'active':''}" data-action="v44-tab" data-slug="${id}" ${slug===id?'aria-pressed="true"':''}>${name} ${v44.pages?.[id]?.published?'✓':''}</button>`).join('')}</div>${v44.error?`<div class="v44-editor-note" role="alert">${E(v44.error)}</div>`:''}${!p?`<p>${v44.loading?'جارٍ تحميل المحتوى...':'اضغط «تحديث الصفحات» لعرض المحتوى.'}</p><button class="v22-btn v22-primary" type="button" data-action="v44-reload">تحديث الصفحات</button>`:`<form id="v44-page-form" class="v22-form" data-v44-slug="${E(slug)}"><input type="hidden" name="slug" value="${E(slug)}"><input type="hidden" name="revision" value="${Number(p.revision)||0}"><label>عنوان الصفحة<input name="title" maxlength="130" required value="${E(p.title||V44_LABELS[slug])}"></label><label>نص الصفحة <small>يمكن كتابة عنوان فرعي مسبوق بـ ## أو عناصر مسبوقة بـ -</small><textarea name="content" maxlength="16000" required>${E(p.content||'')}</textarea></label><div class="v44-editor-note ${p.published?'v44-editor-ok':''}">${p.published?'هذه الصفحة منشورة حاليًا.':'هذه الصفحة مسودة وغير منشورة للزوار.'}${slug!=='about'?' راجع الصياغة القانونية وتوافقها مع عمل الأكاديمية قبل تفعيل النشر.':''}</div><label class="v44-publish"><input name="published" type="checkbox" ${p.published?'checked':''}>نشر الصفحة للعامة بعد المراجعة</label><div class="v44-actions"><button type="submit" class="v22-btn v22-primary">حفظ التعديلات</button><a class="v22-btn v22-secondary" href="./${slug}.html" target="_blank" rel="noopener noreferrer">فتح النسخة المنشورة ↗</a><button type="button" class="v22-btn v22-secondary" data-action="v44-preview">معاينة النص داخل المحرر</button></div></form><div id="v44-preview" hidden class="v44-editor-note" aria-live="polite"></div><small>آخر تحديث: ${p.updatedAt?new Date(Number(p.updatedAt)).toLocaleDateString('ar-EG'):'النص المبدئي'} — نسخة ${Number(p.revision)||0}</small>`}</section>`;
}
async function v44LoadPages(){if(ROLE!=='admin'||!state.user)return;v44.loading=true;v44.error='';try{const result=await backend.request('v44/admin/pages',{token:auth._token()});v44.pages=result.pages||{};}catch(e){v44.error='تعذر تحميل الصفحات: '+message(e);}finally{v44.loading=false;if(state.view==='v44-pages')render();}}
async function v44SavePage(form){if(ROLE!=='admin')throw Error('هذه الوظيفة مخصصة للإدارة');const fd=new FormData(form);const slug=String(fd.get('slug')||'');if(!Object.hasOwn(V44_LABELS,slug))throw Error('صفحة غير صحيحة');const content=String(fd.get('content')||'').trim();const title=String(fd.get('title')||'').trim();const published=fd.has('published');const revision=Number(fd.get('revision'));
 if(!title||!content||title.length>130||content.length>16000)throw Error('يرجى إدخال عنوان ونص مناسبين');if(published&&content.length<120)throw Error('النص المنشور قصير جدًا');
 await post('v44/admin/pages/save',{slug,title,content,published,revision});showtoast('تم حفظ الصفحة '+(published?'ونشرها':'كمسودة'));await v44LoadPages();}
function v44Preview(){const form=document.getElementById('v44-page-form');const target=document.getElementById('v44-preview');if(!form||!target)return;target.hidden=false;target.innerHTML='<strong>'+E(form.elements.title.value)+'</strong><p>'+E(form.elements.content.value).replace(/\n/g,'<br>')+'</p>';}

/* V45: year management, non-destructive safe copies, content visibility & server-enforced attempts. */
const v45={overview:null,loading:false,error:'',sourceYear:'',targetYear:'',type:'public',stage:'primary',grade:'1',subject:'',tab:'years',copyId:'v45_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,10)};
function v45ShuffleIndices(length){const out=Array.from({length},(_,i)=>i);for(let i=out.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[out[i],out[j]]=[out[j],out[i]]}return out;}
function v45CurrentYear(){const entry=Object.values(v45.overview?.years||{}).find(x=>x?.active&&!x?.archived);return entry?.id||''}
function v45YearOptions(withLegacy=false){const years=Object.values(v45.overview?.years||{}).filter(x=>!x.archived).sort((a,b)=>b.id.localeCompare(a.id));return (withLegacy?'<option value="">محتوى سابق بدون سنة</option>':'')+years.map(y=>`<option value="${E(y.id)}" ${v45.targetYear===y.id?'selected':''}>${E(y.title)}</option>`).join('')}
async function v45Load(){if(ROLE!=='admin'||!state.user)return;v45.loading=true;v45.error='';try{const data=await backend.request('v45/admin/overview',{token:auth._token()});v45.overview=data;if(!v45.targetYear)v45.targetYear=v45CurrentYear();}catch(e){v45.error=message(e)}finally{v45.loading=false;if(state.view==='v45-years')render()}}
function v45YearList(){return Object.values(v45.overview?.years||{}).sort((a,b)=>b.id.localeCompare(a.id)).map(y=>`<article class="v45-year-row"><div><strong>${E(y.title)}</strong><small>${E(y.id)} — ${y.archived?'مؤرشفة':y.active?'السنة النشطة':'متاحة'}</small></div><div class="v45-actions">${!y.active&&!y.archived?B('تفعيل','v45-year','v22-primary',`data-id="${E(y.id)}" data-operation="activate"`):''}${!y.archived?B('أرشفة','v45-year','v22-secondary',`data-id="${E(y.id)}" data-operation="archive"`):B('استعادة','v45-year','v22-secondary',`data-id="${E(y.id)}" data-operation="restore"`)}</div></article>`).join('')||'<p>لم تُنشأ سنوات دراسية بعد؛ أنشئ السنة الحالية أولًا.</p>'}
function v45Panel(){const data=v45.overview;
 if(!data)return `${title('السنوات الدراسية وإدارة المحتوى','أدوات النسخ الآمن والأرشفة وإعدادات المحاولات')}${v45.error?`<p class="v22-notice" role="alert">${E(v45.error)}</p>`:''}<section class="v22-card"><p>${v45.loading?'جارٍ جلب البيانات من الخادم...':'اضغط تحميل البيانات للبدء.'}</p>${B('تحميل البيانات','v45-reload','v22-primary')}</section>`;
 const all=[...(data.lessons||[]).map(x=>({...x,kind:'lesson'})),...(data.quizzes||[]).map(x=>({...x,kind:'quiz'})),...(data.files||[]).map(x=>({...x,kind:'file'}))];const hidden=all.filter(x=>x.hidden);const qs=data.quizzes||[];
 const yrs=Object.values(data.years||{}).filter(x=>!x.archived);
 const copySource=(data.lessons||[]).filter(x=>(x.year||'')===v45.sourceYear&&x.type===v45.type&&x.stage===v45.stage&&x.grade===v45.grade&&x.subject===v45.subject);
 const distinct=[...new Map((data.lessons||[]).filter(x=>(x.year||'')===v45.sourceYear).map(x=>[x.type+'|'+x.stage+'|'+x.grade+'|'+x.subject,x])).values()];
 const scopeOpts=distinct.map(x=>`<option value="${E([x.type,x.stage,x.grade,x.subject].join('|'))}" ${[x.type,x.stage,x.grade,x.subject].join('|')===[v45.type,v45.stage,v45.grade,v45.subject].join('|')?'selected':''}>${E((x.type==='azhar'?'أزهري':'عام')+' / '+(stageNames[x.stage]||x.stage)+' / '+x.grade+' / '+subName(x.subject,x.stage,x.grade,x.type))}</option>`).join('');
 return `${title('إدارة السنوات الدراسية والمحتوى','أنشئ سنة دراسية، انسخ المحتوى بطريقة لا تمس الأصل، واستعد الملفات المخفية')}<div class="v45-summary"><div><strong>${Object.keys(data.years||{}).length}</strong> سنوات</div><div><strong>${(data.lessons||[]).length}</strong> دروس</div><div><strong>${(data.quizzes||[]).length}</strong> اختبارات</div><div><strong>${hidden.length}</strong> محتوى مخفي</div></div>
 <section class="v22-card v45-card"><div class="v45-head"><h3>📅 السنوات الدراسية</h3>${B('تحديث','v45-reload','v22-secondary')}</div><p>الأرشفة هنا تحفظ سجلات السنة ولا تحذف دروسها أو نتائج الطلاب. تفعيل السنة يحدد السنة الافتراضية للنسخ.</p><form id="v45-year-form" class="v45-inline"><label>السنة (مثال 2026-2027)<input name="yearId" required pattern="20[0-9]{2}-20[0-9]{2}" placeholder="2026-2027"></label><label>الاسم المعروض<input name="title" required maxlength="100" placeholder="العام الدراسي 2026 / 2027"></label><button class="v22-btn v22-primary" type="submit">إضافة سنة</button></form><div class="v45-year-list">${v45YearList()}</div></section>
 <section class="v22-card v45-card"><h3>📚 نسخ محتوى مقرر إلى سنة جديدة</h3><p>ينسخ الدروس مع الاختبارات والملفات المرتبطة بها إلى سجلات جديدة **مخفية ومسودة**؛ لا يحذف أو يغيّر الأصل ولا ينسخ درجات الطلاب. راجع المحتوى المنسوخ ثم انشره من إدارة المحتوى.</p>
 <form id="v45-copy-form" class="v45-form"><div class="v45-fields"><label>نسخ من سنة<select name="sourceYear" id="v45-copy-source"><option value="" ${v45.sourceYear===''?'selected':''}>محتوى سابق بلا سنة</option>${Object.values(data.years||{}).map(y=>`<option value="${E(y.id)}" ${v45.sourceYear===y.id?'selected':''}>${E(y.title)}</option>`).join('')}</select></label><label>إلى سنة<select name="targetYear" id="v45-copy-target" required><option value="">اختر سنة وجهة...</option>${v45YearOptions()}</select></label></div>
 <label>المقرر المطلوب نسخه<select name="scope" id="v45-copy-scope" required><option value="">${scopeOpts?'اختر مادة...':'لا توجد دروس في السنة المختارة'}</option>${scopeOpts}</select></label><div class="v45-checks"><label><input type="checkbox" name="includeQuizzes" checked> نسخ الاختبارات المرتبطة بالدروس</label><label><input type="checkbox" name="includeFiles" checked> نسخ الملفات المرتبطة بالدروس</label></div><p class="v45-hint">الدروس المطابقة للمقرر الحالي: <strong>${copySource.length}</strong>. لا تُنسخ إضافات المعلمين المنفصلة داخل teacherContentsV6 تلقائيًا؛ راجعها بعد النسخ.</p><button type="submit" class="v22-btn v22-primary" ${!distinct.length||!yrs.length?'disabled':''}>نسخ المقرر بأمان</button></form></section>
 <section class="v22-card v45-card"><h3>👁️ إخفاء المحتوى واستعادته</h3><p>يمكن استعادة كل عنصر من غير حذف بياناته. المحتوى المسودة يحتاج نشرًا مستقلًا بعد إلغاء الإخفاء.</p><div class="v45-list">${hidden.length?hidden.slice(0,150).map(x=>`<article class="v45-item"><div><strong>${E(x.title)}</strong><small>${E(({lesson:'درس',quiz:'اختبار',file:'ملف'})[x.kind])} • ${E(x.year||'بلا سنة')} • ${E(x.subject)}</small></div>${B('إعادة إظهار','v45-visibility','v22-primary',`data-kind="${x.kind}" data-id="${E(x.id)}" data-hidden="false"`)}</article>`).join(''):'<p>لا يوجد محتوى مخفي حاليًا.</p>'}</div><details><summary>إخفاء محتوى منشور</summary><div class="v45-list">${all.filter(x=>!x.hidden).slice(0,150).map(x=>`<article class="v45-item"><div><strong>${E(x.title)}</strong><small>${E(({lesson:'درس',quiz:'اختبار',file:'ملف'})[x.kind])} • ${E(x.year||'بلا سنة')}</small></div>${B('إخفاء','v45-visibility','v22-secondary',`data-kind="${x.kind}" data-id="${E(x.id)}" data-hidden="true"`)}</article>`).join('')}</div></details></section>
 <section class="v22-card v45-card"><h3>🧾 إعداد عدد محاولات الاختبارات</h3><p>يطبّق الحد على الخادم عند حفظ محاولة اختبار مستقل. القيمة صفر تعني عدم وضع حد. هذا الإعداد لا يشمل اختبارات المعلمين المدمجة داخل الدروس.</p><div class="v45-list">${qs.map(x=>`<form id="v45-quiz-${E(x.id)}" class="v45-quiz-row" data-quiz="${E(x.id)}"><div><strong>${E(x.title)}</strong><small>${E(subName(x.subject,x.stage,x.grade,x.type))} • ${x.draft?'مسودة':'متاح للنشر'}</small></div><label>عدد المحاولات<input type="number" name="maxAttempts" min="0" max="20" value="${Number(x.maxAttempts)||0}" required></label><label class="v45-check"><input name="shuffleQuestions" type="checkbox" ${x.shuffleQuestions?'checked':''}> خلط الأسئلة</label><label class="v45-check"><input name="shuffleAnswers" type="checkbox" ${x.shuffleAnswers?'checked':''}> خلط الإجابات</label><button class="v22-btn v22-primary" type="submit">حفظ</button></form>`).join('')||'<p>لا توجد اختبارات مستقلة بعد.</p>'}</div></section>`;
}
async function v45Submit(form){if(ROLE!=='admin')throw Error('الإدارة فقط');const data=new FormData(form);if(form.id==='v45-year-form'){const id=String(data.get('yearId')||''),title=String(data.get('title')||'');await post('v45/admin/years/save',{id,title});showtoast('تمت إضافة السنة الدراسية');return v45Load()}
 if(form.id==='v45-copy-form'){
  const scope=String(data.get('scope')||'').split('|');if(scope.length!==4)throw Error('اختر مقررًا أولًا');const sourceYear=String(data.get('sourceYear')||''),targetYear=String(data.get('targetYear')||'');if(sourceYear===targetYear)throw Error('اختر سنة وجهة مختلفة');
  if(!window.confirm('ستنشأ نسخ جديدة مخفية ومسودات من الدروس والاختبارات والملفات المرتبطة. لن يتم تغيير أي نسخة أصلية. هل تريد المتابعة؟'))return;
  const result=await post('v45/admin/copy/scope',{sourceYear,targetYear,type:scope[0],stage:scope[1],grade:scope[2],subject:scope[3],includeQuizzes:data.has('includeQuizzes'),includeFiles:data.has('includeFiles'),copyId:v45.copyId});v45.copyId='v45_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,10);showtoast(`تم نسخ ${result.counts.lessons||0} درس و${result.counts.quizzes||0} اختبار و${result.counts.files||0} ملف كمحتوى مخفي للمراجعة`);await v45Load();return refresh();}
 if(form.dataset.quiz){const n=Number(data.get('maxAttempts'));if(!Number.isInteger(n)||n<0||n>20)throw Error('الحد من 0 إلى 20');await post('v45/admin/quiz/options',{id:form.dataset.quiz,maxAttempts:n,shuffleQuestions:data.has('shuffleQuestions'),shuffleAnswers:data.has('shuffleAnswers')});showtoast('تم حفظ عدد المحاولات');return v45Load();}
}
async function v45Click(el){const action=el.dataset.action;if(action==='v45-reload')return v45Load();if(action==='v45-year'){const id=el.dataset.id,operation=el.dataset.operation;if(operation==='archive'&&!confirm('أرشفة السنة؟ سيتم حفظ كل بياناتها دون حذف، ولن تكون السنة نشطة.'))return;await post('v45/admin/years/decision',{id,action:operation});showtoast('تم تحديث السنة');return v45Load();}
 if(action==='v45-visibility'){const {kind,id}=el.dataset,hidden=el.dataset.hidden==='true';if(hidden&&!confirm('إخفاء هذا المحتوى عن الطلاب دون حذفه؟'))return;await post('v45/admin/visibility',{kind,id,hidden});showtoast(hidden?'تم إخفاء المحتوى':'تمت استعادة ظهور المحتوى');await v45Load();return refresh();}}

function wrapper(inner){return `<div class="launch-guest">${header()}${inner}<footer class="v22-footer v30-footer"><div><strong>${E(siteName())}</strong><span>${E(v30Footer())} • ${new Date().getFullYear()}</span></div>${v44FooterLinks()}${v30SocialRow(false,'footer')}</footer></div>`}
