async function v49Load(force=false){
 if(!state.ready||!state.user||!['admin','teacher'].includes(ROLE)||document.hidden)return;
 const uid=state.user.uid;if(!force&&Date.now()-v49.at<15000)return;
 const serial=++v49.serial;v49.at=Date.now();v49.loading=true;
 try{const data=await backend.request('v49/badges',{token:auth._token()});if(serial!==v49.serial||uid!==state.user?.uid)return;
   v49.counts=data?.counts&&typeof data.counts==='object'?data.counts:{};v49.uid=uid;v49.snapshotAt=Date.now();v49.lastError=false;
 }catch(err){if(serial===v49.serial){v49.at=0;v49.lastError=true;console.warn('V49 badge refresh failed',message(err));}}
 finally{if(serial===v49.serial){v49.loading=false;if(!v28ShouldDefer())render();else v28PendingPaint=true;}}
}
