function subjectsUI(){const type=state.type,stage=state.stage,grade=state.grade;return `${title('المواد الدراسية',`${educ(type)} • ${gradeName(stage,grade)}`)}${crumb()}<div class="v22-cards">${subjectList().map(s=>{const n=allLessons().filter(l=>(l.type||'public')===type&&l.stage===stage&&String(l.grade)===String(grade)&&l.subject===s.id).length;return `<button class="v22-card" data-action="subject" data-subject="${E(s.id)}" data-type="${E(type)}" data-stage="${E(stage)}" data-grade="${E(grade)}"><div class="v22-illustration"><img src="${E(s.imageUrl?safeURL(s.imageUrl):pic(s.img))}" alt=""></div><h3>${E(s.name)}</h3><p>${n?`${n} درس متاح`:'المادة جاهزة لإضافة الدروس'}</p><span class="v22-link">الدخول للمادة ←</span></button>`}).join('')}</div>`}
function crumb(){return `<div class="v22-breadcrumb"><button data-action="route" data-view="stages">المراحل</button> / ${E(educ(state.type))} ${state.stage?' / '+E(stageNames[state.stage]):''} ${state.grade?' / '+E(gradeName(state.stage,state.grade)):''} ${state.subject?' / '+E(subName(state.subject)):''}</div>`}
// V96: completion is an explicit saved completion flag or a scoped legacy completion record.
function v96CompletedIds(type,stage,grade,subject){
 const done=new Set(Object.entries(val(state.profile?.learningProgress)).filter(([,v])=>v?.completed===true).map(([id])=>String(id)));
 for(const m of getMasteryRows(state.legacyMastery))if(m.type===type&&m.stage===stage&&String(m.grade)===String(grade)&&m.subject===subject&&['completed','mastered','done'].includes(m.status))done.add(String(m.lessonId));
 return done;
}
function v96LessonPresentation(l,completed,unit,quizIds){
 const ids=Array.isArray(l.teacherIds)?l.teacherIds.filter(x=>typeof x==='string'):Object.entries(val(l.teacherIds)).filter(([,v])=>v===true).map(([id])=>id);
 if(l.teacherId&&!ids.includes(l.teacherId))ids.push(l.teacherId);
 const has=x=>Array.isArray(x)?x.length>0:!!x&&typeof x==='object'?Object.keys(x).length>0:false;
 return {id:l.id,title:l.title||'درس تعليمي',subject:l.subject,unit:Number(l.unit)||1,unitLabel:unit?.name||'الوحدة '+(Number(l.unit)||1),unitImageUrl:safeURL(unit?.imageUrl),imageUrl:safeURL(l.imageUrl),teacherIds:ids,teacherName:l.teacherName||'',completed,accessLocked:l.accessLocked===true,
  hasVideo:!!l.videoUrl||has(l.videos)||Number(l.videosCount)>0,hasContent:!!String(l.content||'').trim(),hasQuestions:has(l.questions)||Number(l.questionsCount)>0,hasQuiz:quizIds.has(String(l.id)),hasFiles:has(l.attachments)||has(l.files)};
}
