 return window.EgtazCurriculumV96.render({key:[state.user?.uid||'guest',state.type,state.stage,state.grade,state.subject].join('|'),subjectName:subName(state.subject),heroImageUrl:subjectList().find(x=>x.id===state.subject)?.imageUrl||'',scopeLabel:gradeName(state.stage,state.grade)+' · '+educ(state.type),loggedIn:state.user?.role==='student',lessons:list.map(l=>v96LessonPresentation(l,done.has(String(l.id)),units.find(u=>u.number===(Number(l.unit)||1)),quizIds)),units,teachers:teachers().map(t=>({id:t.id,name:t.name}))});
