function authUI(){return `<div class="v22-auth v22-card">${title(state.view==='register'?'إنشاء حساب جديد':'أهلًا بك مجددًا',ROLE==='teacher'?'دخول المعلم':ROLE==='admin'?'دخول الإدارة':ROLE==='parent'?'دخول ولي الأمر':'ابدأ رحلتك في أكاديمية اجتاز')}${ROLE==='student'?`<div class="v22-tabs"><button class="v22-tab ${(state.view||'')!=='register'?'active':''}" data-action="route" data-view="login">تسجيل الدخول</button><button class="v22-tab ${state.view==='register'?'active':''}" data-action="route" data-view="register">حساب طالب جديد</button><a class="v22-tab" href="parent.html">ولي الأمر</a></div>`:ROLE==='parent'?`<div class="v22-tabs"><button class="v22-tab ${state.view!=='register'?'active':''}" data-action="route" data-view="login">دخول</button><button class="v22-tab ${state.view==='register'?'active':''}" data-action="route" data-view="register">حساب ولي أمر جديد</button></div>`:''}<form id="auth-form" class="v22-form">${state.view==='register'?`<label>الاسم بالكامل<input name="name" required maxlength="100" autocomplete="name"></label>${ROLE==='student'?`<div class="v42-register-scope"><h3>حدد صفك الدراسي</h3><div class="v22-fields">${fields.type}${fields.stage}${fields.grade}</div></div>${v42AvatarPicker('student-01')}`:''}`:''}<label>${ROLE==='student'?'رقم الهاتف أو البريد الإلكتروني':'البريد الإلكتروني'}<input name="email" required autocomplete="username" placeholder="${ROLE==='student'?'01012345678 أو البريد الإلكتروني':'example@email.com'}"></label>${state.view==='register'&&ROLE==='student'?`<label for="v92-guardian-phone">رقم هاتف ولي الأمر <span class="v92-required">*</span><input id="v92-guardian-phone" name="guardianPhone" type="tel" inputmode="tel" autocomplete="tel" required maxlength="25" placeholder="مثال: 01012345678" aria-describedby="v92-guardian-help"></label><small id="v92-guardian-help" class="v92-hint">رقم محمول مصري صحيح من 11 رقمًا، يبدأ بـ 010 أو 011 أو 012 أو 015. يُستخدم للتواصل الإداري ولا يربط الحساب بولي الأمر تلقائيًا.</small><small id="v92-guardian-error" class="v92-feedback" role="status" aria-live="polite"></small>`:''}<label for="v92-password">كلمة المرور<input id="v92-password" name="password" type="password" ${state.view==='register'?'minlength="8" maxlength="72" aria-describedby="v92-password-help v92-password-error"':''} required autocomplete="${state.view==='register'?'new-password':'current-password'}"></label>${state.view==='register'?`<small id="v92-password-help" class="v92-hint">يجب ألا تقل كلمة المرور عن 8 أحرف أو أرقام، ولا تزيد عن 72 بايت. مثال: كلمة من 6 أرقام لا تكفي.</small><small id="v92-password-error" class="v92-feedback" role="status" aria-live="polite"></small>`:''}<button class="v22-btn v22-primary" type="submit">${state.view==='register'?'إنشاء الحساب':'تسجيل الدخول'}</button></form><div class="v22-notice">${ROLE==='admin'?'إذا لم يُنشأ حساب الإدارة بعد، استخدم صفحة إعداد الإدارة الموجودة في المشروع.':'بيانات حسابك تُتحقق من خادم الأكاديمية، ولا توجد حسابات تجريبية وهمية في هذه النسخة.'}</div></div>`}
