function normalizeQuestion(q){const choices=Array.isArray(q.options)?q.options:typeof q.options==='object'?Object.values(q.options||{}):Array.isArray(q.opts)?q.opts:[];const options=choices.map(x=>typeof x==='object'?(x.text??x.label??x.value??''):x).map(String);let answer=q.correctAnswer??q.correct??q.answerIndex??q.answer;let ix=Number(answer);if(answer===undefined||answer===null||answer==='')ix=-1;else if(!Number.isInteger(ix)||ix<0||ix>=options.length)ix=options.indexOf(String(answer));return{question:q.question||q.q||q.text||'',options,correct:ix,hint:q.hint||q.why||q.explanation||''}}
function quizSourceQuestions(source){
 if(!source||source.accessLocked)return [];
 if(source.assessmentMode==='interactive')return window.EgtazV57?.normalizeClient?.(source)||[];
 const items=Array.isArray(source.questions)?source.questions:Object.values(val(source.questions));
 return items.filter(x=>x&&typeof x==='object').map(normalizeQuestion).filter(x=>x.question&&x.options.length>=2&&(source.assessmentMode==='exam'||(x.correct>=0&&x.correct<x.options.length)));
}
