async function saveScore(){if(state.quizSaved||!state.user||state.user.role!=='student')return;const quiz=state.quiz;if(quiz?.interactive)return window.EgtazV57.saveScore(state,post,read,v28AnnounceUpdate);if(!quiz||state.answers.length!==quiz.questions.length||state.answers.some((a,i)=>!Number.isInteger(a)||a<0||a>=quiz.questions[i].options.length))throw Error('أكمل كل إجابات الاختبار قبل الحفظ');const response=await post('student/quiz/submit',{lessonId:state.id,quizId:quiz.id,teacherId:quiz.teacherId||'',sourceType:quiz.sourceType,sourceVersion:quiz.sourceVersion,attemptId:state.quizAttemptId,answers:state.answers.slice(),...(quiz.questionOrder?{questionOrder:quiz.questionOrder}:{}),...(quiz.optionOrders?{optionOrders:quiz.optionOrders}:{})});if(!response?.result||!Number.isInteger(Number(response.result.score)))throw Error('الخادم لم يؤكد حفظ النتيجة');state.quizSaved=true;state.quizReview=response.review||null;state.quizSavedResult=response.result;state.profile=state.profile||{};state.profile.quizResultsV22=val(state.profile.quizResultsV22);state.profile.quizResultsV22[quiz.id]=response.result;try{state.profile=await read('studentProfilesV3/'+state.user.uid)}catch(e){console.warn('Quiz saved, profile reread delayed',e)}v28AnnounceUpdate()}
