// V30 Stage 2 — manage unit metadata and lesson order without changing lesson IDs.
function adminUnitsUI(t,stage,grade,subjects){
 const sid=subjects.some(x=>x.id===state.v30UnitSubject)?state.v30UnitSubject:subjects[0]?.id;
 if(!sid)return '';
 const lessons=rows(state.public.lessons).filter(l=>(l.type||'public')===t&&l.stage===stage&&String(l.grade)===grade&&l.subject===sid);
 const units=v30Units(t,stage,grade,sid,lessons);
 const editing=units.find(u=>u.id===state.v30EditingUnit);
 const ordered=lessons.sort(v30LessonComparator(t,stage,grade,sid));
 const visibleLessons=units.map(unit=>{const items=ordered.filter(l=>(Number(l.unit)||1)===unit.number);
 return `<section class="v30-unit-block ${unit.isHidden?'is-hidden':''}"><div class="v30-unit-title">${unit.imageUrl?`<img src="${E(unit.imageUrl)}" alt="" loading="lazy">`:''}<div><strong>${E(unit.name)}</strong><small>رقم الوحدة ${unit.number} • ترتيب ${unit.order} • ${items.length} درس • ${unit.isHidden?'مخفية من قائمة الطالب':'ظاهرة للطالب'}</small></div></div><div class="v22-btnrow">${B('تعديل الوحدة','v30-edit-unit','v22-secondary',`data-unit="${unit.number}"`)}${B(unit.isHidden?'إظهار':'إخفاء','v30-toggle-unit',unit.isHidden?'v22-primary':'v22-secondary',`data-unit="${unit.number}"`)}</div>
 ${items.length?items.map(l=>`<form class="v30-lesson-sort" data-lesson-id="${E(l.id)}"><div class="v30-lesson-image"><img src="${E(safeURL(l.imageUrl)||pic('books.png'))}" alt="" loading="lazy"></div><div class="v30-lesson-summary"><strong>${E(l.title||'درس بدون عنوان')}</strong><small>ترتيب ${Number(l.order??0)} • ${l.isHidden?'درس مخفي':'درس منشور'}</small><div class="v30-lesson-controls"><label>ترتيب<input aria-label="ترتيب الدرس" name="order" type="number" min="0" max="9999" required value="${Number(l.order??0)}"></label><label class="v30-lesson-cover">رابط صورة الدرس<input name="imageUrl" type="url" value="${E(l.imageUrl||'')}" placeholder="https://..."></label></div></div><div class="v30-lesson-btns"><button class="v22-btn v22-primary" type="submit">حفظ</button>${B('تعديل كامل','edit-lesson','v22-secondary',`data-id="${E(l.id)}"`)}</div></form>`).join(''):`<p class="v26-hint">لا توجد دروس في هذه الوحدة. عند إضافة درس اختر رقمها: ${unit.number}.</p>`}</section>`}).join('');
 return `<section class="v30-units-workspace" id="v30-unit-workspace"><div class="v30-workspace-title"><div><h2>الوحدات وترتيب الدروس</h2><p>التحكم في الاسم والغلاف وترتيب الوحدات والدروس من نفس لوحة الإدارة، مع الاحتفاظ بكل الاختبارات والفيديوهات المرتبطة.</p></div><span class="v22-chip">${units.length} وحدة • ${lessons.length} درس</span></div>
 <div class="v22-card v30-unit-subject"><label>المادة المطلوب تنظيمها <select id="v30-unit-subject" aria-label="اختيار مادة لتنظيم وحداتها">${subjects.map(x=>`<option value="${E(x.id)}" ${x.id===sid?'selected':''}>${E(x.name)}${x.isHidden?' (مخفية)':''}</option>`).join('')}</select></label><p>إخفاء الوحدة يخفيها من قائمة المادة عند الطالب، ولا يحذف الدروس أو يمنع فتح رابط درس محفوظ مباشرةً. صلاحيات المحتوى تحكمها إعدادات الخادم.</p></div>
 <div class="v30-unit-columns"><div class="v22-card"><h3>الوحدات ودروسها</h3>${units.length?visibleLessons:empty('لا توجد وحدات بعد','أضف أول وحدة من النموذج المجاور، أو أنشئ درسًا برقم وحدة.')}</div>
 <form class="v22-card v22-form" id="v30-unit-form"><h3>${editing?'تعديل بيانات الوحدة':'إضافة وحدة'}</h3><label>رقم الوحدة<input type="number" name="unit" min="1" max="99" required ${editing?'readonly':''} value="${editing?.number||''}" placeholder="1"></label><label>اسم الوحدة<input name="name" maxlength="100" required value="${E(editing?.hasCustom?editing.name:'')}" placeholder="مثال: النحو والتراكيب"></label><label>رابط صورة الوحدة<input type="url" name="imageUrl" value="${E(editing?.imageUrl||'')}" placeholder="https://..."></label><label>ترتيب الوحدة<input name="order" type="number" min="0" max="9999" step="1" required value="${editing?editing.order:(units.length+1)*10}"></label><div class="v22-btnrow"><button class="v22-btn v22-primary" type="submit">${editing?'حفظ الوحدة':'إضافة الوحدة'}</button>${editing?B('إلغاء التعديل','v30-unit-cancel','v22-secondary'):''}</div><p class="v22-notice">نحفظ بيانات الوحدة ضمن إعدادات الأكاديمية. الدروس تبقى بمعرّفاتها وأرقام وحداتها الحالية؛ لا يوجد حذف للدروس عند تغيير ترتيب الوحدة.</p></form></div></section>`;
}
function adminQuestionBankUI(){const bank=rows(state.v25?.questionBank||{}).slice(0,160);return `${title('بنك الأسئلة والاختبارات','اعرض الأسئلة المحفوظة وانتقل لمنشئ الاختبارات الجديد')}<div class="v22-btnrow">${B('إنشاء اختبار من أسئلة جديدة','route','v22-primary','data-view="create-quiz"')}${B('إدارة الاختبارات المنشورة','route','v22-secondary','data-view="content"')}</div><div class="v22-stats">${v25Stat('أسئلة البنك المحملة',rows(state.v25?.questionBank||{}).length)}${v25Stat('الاختبارات المنشورة',allQuizzes().length)}</div><div class="v22-card"><h3>الأسئلة المحفوظة</h3>${state.v25?.loading?'جارٍ قراءة بنك الأسئلة...':bank.length?`<div class="v24-filter"><label>البحث<input data-v24-filter="v25-questions" placeholder="ابحث عن سؤال..."></label></div><div id="v25-questions">${bank.map(q=>`<div class="v22-line" data-v24-row="${E(q.question||q.text||'')}"><div><strong>${E(q.question||q.text||'السؤال')}</strong><small>${E(q.subject||'')} • ${E(q.status||'')}</small></div></div>`).join('')}</div>`:empty('لا توجد أسئلة أو تعذر قراءة البنك','أنشئ اختبارًا أو أضف أسئلة من نظام الاختبارات.')}</div>`}
const v25Perms={createLiveSessions:'إنشاء الحصص المباشرة',publishLiveSessions:'نشر الحصص المباشرة دون موافقة الإدارة',publishQuestions:'نشر أسئلة البنك مباشرة',publishLessons:'نشر الدروس مباشرة',publishQuizzes:'نشر الاختبارات مباشرة',publishFiles:'نشر الملفات مباشرة',publishProfile:'نشر تحديث الملف دون مراجعة',publishEdits:'نشر تعديل المحتوى',createGroups:'إنشاء مجموعات',shareContent:'مشاركة المحتوى',createChallenges:'إنشاء التحديات',publishChallenges:'نشر التحديات مباشرة دون مراجعة',createTournaments:'إنشاء البطولات',publishTournaments:'نشر البطولات التدريبية مباشرة',createCourses:'إنشاء الكورسات',publishCourses:'نشر الكورسات وتعديلاتها مباشرة دون مراجعة'};
function adminTeacherPermissionsUI(){const list=rows(state.liveData.adminTeachers);const id=state.v25TeacherId&&list.some(t=>t.id===state.v25TeacherId)?state.v25TeacherId:list[0]?.id;const t=list.find(t=>t.id===id);return `${title('صلاحيات المعلمين','تحكم في نشر المحتوى والفصول من نفس لوحة الإدارة الجديدة')}${!list.length?empty('لا يوجد معلمون','أضف أول معلم من قسم إدارة المعلمين.'):`<div class="v22-two"><section class="v22-card"><h3>اختر المعلم</h3>${list.map(x=>`<button class="v25-teacher-line ${x.id===id?'active':''}" data-action="v25-select-teacher" data-id="${E(x.id)}"><strong>${E(x.name||x.displayName||x.email||'معلم')}</strong><small>${x.isArchived?'مؤرشف':x.isActive===false?'موقوف':'نشط'}</small></button>`).join('')}</section><form class="v22-card v22-form" id="v25-permissions-form"><h3>صلاحيات ${E(t.name||'المعلم')}</h3><input type="hidden" name="teacherId" value="${E(id)}">${Object.entries(v25Perms).map(([k,name])=>`<label class="v25-switch-row"><input type="checkbox" name="${k}" ${(t.permissions?.[k]===true||(t.permissions?.[k]===undefined&&['createGroups','shareContent','createChallenges','createLiveSessions','createCourses'].includes(k)))?'checked':''}><span>${E(name)}</span></label>`).join('')}<button class="v22-btn v22-primary" type="submit">حفظ الصلاحيات</button><div class="v25-danger-zone"><h4>حالة الحساب</h4>${B(t.isArchived||t.accountState==='archived'?'استعادة حساب المعلم':'أرشفة حساب المعلم',t.isArchived||t.accountState==='archived'?'v25-restore':'v25-archive','v22-secondary',`data-id="${E(id)}"`)}</div></form></div>`}`}
function teacherGroupUI(){const list=state.v25?.groups||[];const assignments=Array.isArray(state.teacherProfile.assignments)?state.teacherProfile.assignments:rows(state.teacherProfile.assignments);return `${title('الفصول والمجموعات','أنشئ مجموعة لطلابك بكود انضمام، من داخل لوحة المعلم الجديدة')}<div class="v22-two"><form class="v22-card v22-form" id="v25-group-form"><h3>مجموعة جديدة</h3><label>اسم المجموعة<input name="name" required maxlength="90" placeholder="مجموعة النحو"></label><label>الوصف<input name="description" maxlength="300"></label><label>المادة والصف المسند<select name="assignment" required>${assignments.map((a,i)=>`<option value="${i}">${E((a.subjectName||a.subject||'المادة')+' — '+(stageNames[a.stage]||a.stage||'')+' — الصف '+(a.grade||''))}</option>`).join('')}</select></label><button class="v22-btn v22-primary" type="submit" ${!assignments.length?'disabled':''}>إنشاء المجموعة</button>${!assignments.length?`<p class="v25-clarify">يجب أن تسند الإدارة للمعلم مادة وصفًا قبل إنشاء مجموعة.</p>`:''}</form><section class="v22-card"><h3>مجموعاتي (${list.length})</h3>${state.v25?.loading?'<p>جاري التحميل...</p>':list.length?list.map(g=>`<div class="v25-group-card"><strong>${E(g.name||'مجموعة')}</strong><p>${E(g.description||'')}</p><small>كود الانضمام: <b dir="ltr">${E(g.code||'')}</b> • ${Number(g.membersCount||0)} طالب</small><div class="v22-btnrow">${B(g.active===false?'تفعيل':'إيقاف مؤقت','v25-group-toggle','v22-secondary',`data-id="${E(g.id)}" data-active="${g.active===false?'true':'false'}"`)}${Number(g.membersCount||0)>0?'<small class="v25-clarify">الفصل يضم طلابًا؛ للإيقاف استخدم الزر السابق بدل الحذف.</small>':B('حذف','v25-group-delete','v22-danger',`data-id="${E(g.id)}"`)}</div></div>`).join(''):empty('لا توجد مجموعات بعد','أنشئ مجموعتك الأولى من النموذج.')}</section></div>`}



function v25LoadPanel(view){if(!state.user||!state.ready)return;const authId=state.user.uid;
 const scoped={
 'question-bank':()=>read('questionBankV4').then(x=>state.v25.questionBank=x),
 'teacher-groups':()=>backend.request('teacher/groups',{token:auth._token()}).then(x=>state.v25.groups=x.groups||[]),
 'teacher-students':()=>Promise.all([backend.request('teacher/at-risk',{token:auth._token()}),backend.request('teacher/analytics/summary',{token:auth._token()})]).then(([a,b])=>{state.v25.atRisk=a;v31p2.analytics=b}),
 'teacher-assignments':()=>Promise.all([backend.request('teacher/assignments/list',{token:auth._token()}),backend.request('teacher/groups',{token:auth._token()})]).then(([a,b])=>{v31p2.assignments=a.items||[];v31p2.groups=b.groups||[]}),
 'teacher-analytics':()=>{v56.loading=true;v56.error='';v56.insights=null;return Promise.all([backend.request('teacher/analytics/summary',{token:auth._token()}),backend.request('teacher/insights/v56',{token:auth._token()}).catch(e=>({error:message(e)}))]).then(([summary,insights])=>{if(state.user?.uid!==authId)return;v31p2.analytics=summary;v56.error=insights.error?'تعذر قراءة التقرير المتقدم. حاول تحديث الصفحة.':'';v56.insights=insights.error?null:insights;}).finally(()=>{v56.loading=false;});}
 };if(!scoped[view])return;const requestId=state.v25.requestId=(state.v25.requestId||0)+1;state.v25.loading=true;v31p2.loading=true;v31p2.error='';render();Promise.resolve().then(scoped[view]).catch(e=>{if(state.user?.uid===authId){v31p2.error=message(e);showtoast('تعذر قراءة بيانات القسم: '+message(e))}}).finally(()=>{if(state.v25.requestId===requestId&&state.user?.uid===authId){state.v25.loading=false;v31p2.loading=false;if(state.view===view)render()}})}

/* V31 phase 3: secure summary endpoints return only authorized report fields. */
const v31p3={teacher:null,parent:null,parentKid:'',loading:false,parentLoading:false,error:'',parentError:'',requestId:0,parentRequestId:0};
async function v31p3LoadTeacher(){
 if(ROLE!=='teacher'||!state.user)return;
 const uid=state.user.uid,requestId=++v31p3.requestId;v31p3.loading=true;v31p3.error='';render();
 try{const r=await backend.request('teacher/students/progress',{token:auth._token()});if(state.user?.uid!==uid||requestId!==v31p3.requestId)return;v31p3.teacher=r;}
 catch(err){if(state.user?.uid===uid&&requestId===v31p3.requestId)v31p3.error=message(err)}
 finally{if(state.user?.uid===uid&&requestId===v31p3.requestId){v31p3.loading=false;if(['teacher-students','teacher-analytics'].includes(state.view))render()}}
}
async function v31p3LoadParent(){
 if(ROLE!=='parent'||!state.user)return;
 const uid=state.user.uid,sid=state.kid||Object.keys(state.kids)[0];if(!sid)return;
 const requestId=++v31p3.parentRequestId;v31p3.parentKid=sid;v31p3.parentLoading=true;v31p3.parentError='';render();
 try{const r=await backend.request('parent/children/learning-report?studentId='+encodeURIComponent(sid),{token:auth._token()});if(state.user?.uid!==uid||requestId!==v31p3.parentRequestId)return;v31p3.parent=r;}
 catch(err){if(state.user?.uid===uid&&requestId===v31p3.parentRequestId)v31p3.parentError=message(err)}
 finally{if(state.user?.uid===uid&&requestId===v31p3.parentRequestId){v31p3.parentLoading=false;if(state.view==='progress')render()}}
}
function v31p3TeacherUI(){
 const r=v31p3.teacher,items=r?.items||[];
 return `<section class="v22-card v31p3-report"><div class="v31p3-heading"><h3>تقرير جميع الطلاب ضمن تكليفك</h3><button class="v22-btn v22-secondary" data-action="v31p3-refresh">تحديث التقرير</button></div>
 <p class="v22-notice">الدرجات مأخوذة من المحاولات والواجبات المصححة فقط. عدم أداء اختبار لا يُحسب صفرًا.</p>
 ${v31p3.error?`<p role="alert">${E(v31p3.error)}</p>`:''}
 ${v31p3.loading?'<p>جارٍ جلب التقرير من الخادم...</p>':r?`<div class="v22-stats">${v25Stat('طلاب ضمن التكليف',r.totalScopedStudents??0)}${v25Stat('واجبات مصححة',r.homeworkGraded??0)}${v25Stat('تسليمات تنتظر التقييم',r.homeworkSubmitted??0)}${v25Stat('واجبات فات موعدها',r.homeworkOverdue??0)}</div>
 ${items.length?`<label class="v31p3-search">ابحث عن طالب<input data-v31p3-filter="v31p3-students" placeholder="اسم الطالب..."></label><div id="v31p3-students">${items.map(x=>`<article class="v31p3-student" data-v31p3-row="${E(x.name||'')}"><div><strong>${E(x.name||'طالب')}</strong><small>${E(stageNames[x.stage]||'')} — الصف ${E(x.grade||'')}</small></div><div><span>الاختبارات: ${x.quizAverage==null?'لا توجد محاولات':E(x.quizAverage)+'%'}</span><span>الواجبات: ${x.homeworkAverage==null?'لم يُقيّم بعد':E(x.homeworkAverage)+'%'}</span><small>${Number(x.homeworkGraded||0)} مصحح • ${Number(x.homeworkSubmitted||0)} ينتظر التقييم • ${Number(x.homeworkOverdue||0)} متأخر</small></div></article>`).join('')}</div>`:empty('لا يوجد طلاب ضمن نطاق تكليفك','عند تسجيل طلاب بالصفوف والمواد المسندة ستظهر بياناتهم هنا.')}`:empty('لا يوجد تقرير محمل','اضغط تحديث التقرير لاسترجاع البيانات من الخادم.')}</section>`;
}
function v31p3ParentUI(sid){const r=v31p3.parentKid===sid?v31p3.parent:null,h=r?.homework,items=h?.items||[];
 return `<section class="v22-card v31p3-report"><div class="v31p3-heading"><h3>متابعة الواجبات الدراسية</h3><button class="v22-btn v22-secondary" data-action="v31p3-refresh">تحديث الواجبات</button></div>
 ${v31p3.parentError&&v31p3.parentKid===sid?`<p role="alert">${E(v31p3.parentError)}</p>`:''}
 ${v31p3.parentLoading?'<p>جارٍ جلب الواجبات من الخادم...</p>':h?`<div class="v22-stats">${v25Stat('إجمالي الواجبات',h.total??0)}${v25Stat('تم تقييمها',h.graded??0)}${v25Stat('بانتظار التقييم',h.submitted??0)}${v25Stat('متأخرة دون تسليم',h.overdue??0)}${v25Stat('متوسط الواجبات',h.average==null?'لا توجد درجات':h.average+'%')}</div>
 ${items.length?items.map(x=>`<article class="v31p3-student"><div><strong>${E(x.title||'واجب')}</strong><small>${E(x.subject||'')} • موعد التسليم: ${E(v31Date(x.dueAt))}</small></div><div><strong>${x.status==='graded'?E(x.score)+'/100':x.status==='submitted'?'بانتظار التقييم':x.status==='overdue'?'متأخر':'لم يُسلَّم'}</strong>${x.status==='graded'&&x.feedback?`<small>تعليق المعلم: ${E(x.feedback)}</small>`:''}</div></article>`).join(''):empty('لا توجد واجبات حاليًا','ستظهر الواجبات المعتمدة للصف والمجموعة هنا.')}`:empty('تقرير الواجبات لم يُحمّل بعد','اضغط تحديث الواجبات لقراءته من الخادم.')}</section>`;}
/* V31 phase 2: scoped homework, submissions and verified-score analytics. */
