 <label>المجموعة (عند اختيار مجموعة)<select name="targetGroupId"><option value="">اختر المجموعة</option>${groups.map(g=>`<option value="${E(g.id)}" data-type="${E(g.type||'public')}" data-stage="${E(g.stage||'')}" data-grade="${E(g.grade||'')}" data-subject="${E(g.subject||'')}">${E(g.name||'مجموعة')}</option>`).join('')}</select></label>
