function teacherAssignmentsUI(){const items=v31p2.assignments;const opened=items.find(a=>a.id===v31p2.openId);return `${title('الواجبات والتسليمات','أرسل واجبًا لصفك أو مجموعتك ثم راجع إجابات الطلاب وقيّمها')}
 <div class="v22-stats">${v25Stat('واجبات معتمدة',items.filter(a=>(a.status||'published')==='published').length)}${v25Stat('بانتظار الإدارة',items.filter(a=>a.status==='pending').length)}${v25Stat('تسليمات للواجب المفتوح',opened?v31p2.submissions.length:'—')}${v25Stat('تم تقييمها',opened?v31p2.submissions.filter(x=>x.status==='graded').length:'—')}</div>
 ${v31p2.error?`<div class="v22-card" role="alert">${E(v31p2.error)}</div>`:''}
 <div class="v22-two v31p2-dual">${v31AssignmentForm()}<section class="v22-card"><h3>واجباتي (${items.length})</h3>${v31p2.loading?'<p>جارٍ تحميل الواجبات...</p>':items.length?items.map(a=>`<article class="v31p2-item"><strong>${E(a.title||'واجب')}</strong><small>${E(v31ScopeName(a))} • آخر موعد ${E(v31Date(a.dueAt))} • ${a.status==='pending'?'قيد المراجعة':a.status==='rejected'?'مرفوض':'منشور'}</small><p>${E(a.instructions||a.description||'')}</p><div class="v22-btnrow">${B('التسليمات والتقييم','v31p2-open','v22-primary',`data-id="${E(a.id)}"`)}${a.status==='published'?B('مشاركة عبر واتساب','v47-share','v22-secondary',`data-id="${E(a.id)}"`):''}${B('حذف','v25-assignment-delete','v22-danger',`data-id="${E(a.id)}"`)}</div></article>`).join(''):empty('لا توجد واجبات منشورة','أنشئ واجبًا جديدًا من النموذج الموجود أمامك.')}</section></div>
 ${opened?`<section class="v22-card v31p2-submissions"><h3>تسليمات: ${E(opened.title||'الواجب')}</h3>${v31p2.loading?'<p>جارٍ التحميل...</p>':v31p2.submissions.length?v31p2.submissions.map(x=>`<div class="v31p2-submission"><div><strong>${E(x.studentName||'طالب')}</strong><small>تاريخ التسليم: ${E(v31Date(x.submittedAt))} • ${x.late?'تسليم متأخر':'في الموعد'} • ${x.status==='graded'?'تم التقييم':'بانتظار التقييم'}</small><div class="v31p2-answer">${E(x.answer||'تم إرسال رابط فقط')}</div>${safeURL(x.link)?`<a target="_blank" rel="noopener noreferrer" href="${E(safeURL(x.link))}">فتح مرفق الطالب ↗</a>`:''}</div><form class="v31p2-grade-form"><input type="hidden" name="assignmentId" value="${E(opened.id)}"><input type="hidden" name="studentId" value="${E(x.studentId)}"><label>الدرجة من 100<input type="number" name="score" min="0" max="100" required value="${x.score??''}"></label><label>تعليق المعلم<textarea name="feedback" maxlength="1500" rows="2">${E(x.feedback||'')}</textarea></label><button class="v22-btn v22-primary">حفظ التقييم</button></form></div>`).join(''):empty('لا توجد تسليمات بعد','عند تسليم الطلاب واجباتهم ستظهر هنا.')}</section>`:''}`}
function studentAssignmentsUI(){const items=v31p2.studentItems;return `${title('واجباتي الدراسية','الواجبات المنشورة لصفك أو المجموعات التي انضممت إليها')}${v31p2.error?`<div class="v22-card" role="alert">${E(v31p2.error)}</div>`:''}
 ${v31p2.studentLoading?empty('جارٍ تحميل الواجبات','نقرأ الواجبات من خادم الأكاديمية...'):!v32.assignmentLoaded?`<div class="v22-card" role="alert">تعذر تحميل الواجبات حاليًا. ${B('إعادة المحاولة','v532-retry-assignments','v22-secondary')}</div>`:items.length?`<div class="v31p2-student-grid">${items.map(a=>{const r=v31p2.mySubmissions[a.id],status=r?.status||'new';return `<article class="v22-card v31p2-item"><h3>${E(a.title||'واجب')}</h3><small>${E(subName(a.subject,a.stage,a.grade,a.type))} • آخر موعد: ${E(v31Date(a.dueAt))}</small><p>${E(a.instructions||a.description||'')}</p><div class="v31p2-status">${status==='graded'?`تم التقييم: ${E(r.score)} / 100${r.feedback?` — ${E(r.feedback)}`:''}`:status==='submitted'?'تم التسليم — بانتظار تقييم المعلم':'لم يتم التسليم بعد'}</div>${status!=='graded'?`<form class="v22-form v31p2-student-form"><input type="hidden" name="assignmentId" value="${E(a.id)}"><label>إجابة الواجب<textarea name="answer" rows="3" maxlength="12000" placeholder="اكتب الإجابة هنا"></textarea></label><label>رابط مرفق اختياري<input name="link" type="url" placeholder="https://..."></label><button class="v22-btn v22-primary">${status==='submitted'?'تحديث التسليم':'إرسال الواجب'}</button></form>`:''}</article>`}).join('')}</div>`:empty('لا توجد واجبات لصفك حاليًا','عندما ينشر المعلم واجبًا مناسبًا لصفك سيظهر هنا.')}`}
function teacherStudentsUI(){const data=state.v25?.atRisk,students=data?.students||[],agg=v31p2.analytics||{};return `${title('الطلاب والمتابعة','مؤشرات لطلاب المواد والصفوف المسندة إليك فقط')}
 <div class="v22-stats">${v25Stat('طلاب ضمن نطاق تكليفك',Number(agg.students??data?.totalScopedStudents??0))}${v25Stat('حالات تحتاج متابعة',students.length)}${v25Stat('محاولات اختبارات موثقة',Number(agg.attempts||0))}</div>
 <div class="v22-card"><h3>طلاب يحتاجون متابعة</h3>${state.v25?.loading?'جارٍ تحميل التقرير...':students.length?students.map(x=>`<article class="v31p2-item"><strong>${E(x.name||'طالب')}</strong><small>${E((x.reasons||[]).join(' • '))}</small><small>${x.averageScore==null?'لم يخض اختبارات موثقة بعد':`متوسط الاختبارات: ${E(x.averageScore)}%`}</small></article>`).join(''):empty('لا توجد حالات تحتاج متابعة','أو لم يُسجَّل نشاط كافٍ بعد للتقييم.')}</div>${v31p3TeacherUI()}`}
/* V56: isolated teacher analytics, no cross-student personal data in reports. */
const v56={insights:null,error:'',loading:false};
function v56TeacherUI(){
 const data=v56.insights;
 if(v56.loading&&!data)return `<section class="v22-card v56-panel" aria-busy="true"><h3>تقرير الفصول والواجبات المتقدم</h3><p>جارٍ قراءة الإحصاءات المعتمدة...</p></section>`;
 if(v56.error)return `<section class="v22-card v56-panel" role="alert"><h3>تقرير الفصول والواجبات المتقدم</h3><p>${E(v56.error)}</p></section>`;
 if(!data)return `<section class="v22-card v56-panel"><h3>تقرير الفصول والواجبات المتقدم</h3><p>افتح التحليلات لتحديث التقرير.</p></section>`;
 const summary=data.assignmentSummary||{},assignments=data.assignments||[],groups=data.groups||[],hard=data.hardQuestions||[];
 const fmt=x=>Number.isFinite(Number(x))?Number(x).toLocaleString('ar-EG'):'—';
 const pct=x=>x==null?'لا توجد تكليفات':'%'+fmt(x);
 return `<section class="v56-panel" aria-label="تقارير المعلم المتقدمة"><h2>إنجاز الواجبات والفصول</h2>
 <p class="v56-muted">المؤشرات محسوبة من واجباتك المنشورة وعضويات المجموعات النشطة فقط؛ لا تعرض أسماء الطلاب أو إجاباتهم.</p>
 <div class="v22-stats">${v25Stat('نسبة إنجاز الواجبات',pct(summary.completionPercent))}${v25Stat('تكليفات للطلاب',fmt(summary.eligibleTotal))}${v25Stat('تم التسليم',fmt(summary.completed))}${v25Stat('تأخر التسليم',fmt(summary.overdue))}${v25Stat('المجموعات النشطة',fmt(data.groupSummary?.active||0))}</div>
 <div class="v22-two">
 <section class="v22-card"><h3>الواجبات حسب الإنجاز</h3>${assignments.length?assignments.map(a=>`<div class="v56-report-line"><div><strong>${E(a.title||'واجب')}</strong><small>${E(a.subject||'')} • ${fmt(a.completed)} من ${fmt(a.eligible)} • متأخر ${fmt(a.overdue)}</small></div><div class="v56-progress" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Number(a.completionPercent||0)}"><i style="width:${Number(a.completionPercent||0)}%"></i></div><small>${pct(a.completionPercent)}</small></div>`).join(''):empty('لا توجد واجبات معتمدة','ستظهر نسبة إنجاز الواجبات بعد نشرها وتسليم الطلاب.')}</section>
 <section class="v22-card"><h3>المجموعات الدراسية</h3>${groups.length?groups.map(g=>`<div class="v22-line"><strong>${E(g.name||'مجموعة')}</strong><small>${g.active?'نشطة':'موقوفة'} • ${fmt(g.members)} عضو مؤهل</small></div>`).join(''):empty('لا توجد مجموعات','يمكنك إنشاء مجموعة وإرسال كود الانضمام للطلاب.')}</section></div>
 <section class="v22-card"><h3>الأسئلة الأكثر تكرارًا في الأخطاء</h3><p class="v56-muted">تظهر من دفتر أخطاء الطلاب في الاختبارات المنشورة التابعة لمحتواك فقط. العدد هو مرات الخطأ المسجلة وليس نسبة صعوبة السؤال.</p>${hard.length?hard.map(q=>`<div class="v56-hard-row"><strong>${E(q.question||'سؤال')}</strong><small>${E(q.subject||'')} • ${fmt(q.wrongCount)} مرة خطأ</small></div>`).join(''):empty('لا توجد أخطاء مؤهلة للعرض','قد لا تحتوي الاختبارات القديمة على تفاصيل أخطاء محفوظة.')}</section>
 ${data.limits?.partial?'<p class="v56-muted" role="status">التقرير جزئي بسبب كبر حجم السجلات؛ راجع لوحات المتابعة التفصيلية للحصول على بقية البيانات.</p>':''}</section>`;
}
function teacherAnalyticsUI(){const d=v31p2.analytics||{},pub=rows(state.liveData.myContent),subs=rows(state.liveData.mySubmissions);return `${title('تحليلات المعلم','نتائج محسوبة من المحاولات المحفوظة في قاعدة البيانات، دون أرقام تجريبية')}
 <div class="v22-stats">${v25Stat('طلاب ضمن نطاق التكليف',d.students??'—')}${v25Stat('محاولات اختبارات',d.attempts??'—')}${v25Stat('متوسط الدرجة',d.average==null?'لا توجد نتائج':d.average+'%')}${v25Stat('محتوى منشور',pub.length)}${v25Stat('طلبات معلّقة',subs.filter(x=>x.status==='pending').length)}</div>
 <div class="v22-two"><section class="v22-card"><h3>توزيع درجات المحاولات</h3>${d.attempts?Object.entries(d.buckets||{}).map(([band,count])=>`<div class="v31p2-bar"><span>${E(band)}%</span><div><i style="width:${Math.max(0,Math.min(100,100*count/d.attempts))}%"></i></div><strong>${Number(count)}</strong></div>`).join(''):empty('لا توجد اختبارات محلولة بعد','ستظهر التحليلات عندما يحل الطلاب اختبارات موادك.')}</section>
 <section class="v22-card"><h3>النتائج حسب المادة</h3>${(d.subjects||[]).length?d.subjects.map(x=>`<div class="v22-line"><strong>${E(v31Scopes().find(a=>a.subject===x.subject)?.subjectName||x.subject)}</strong><small>${Number(x.attempts)} محاولة • متوسط ${Number(x.average)}%</small></div>`).join(''):empty('لا توجد بيانات كافية','تظهر الإحصائيات من المحاولات الموثّقة فقط.')}</section></div>${v56TeacherUI()}${v31p3TeacherUI()}`}
async function v31p2LoadStudent(){if(ROLE!=='student'||!state.user)return;const id=state.user.uid;v31p2.studentLoading=true;v31p2.error='';v32.assignmentError='';v32.assignmentLoaded=false;render();try{const result=await backend.request('student/assignments',{token:auth._token()});if(state.user?.uid!==id)return;v31p2.studentItems=result.items||[];v31p2.mySubmissions=result.submissions||{};v32.assignmentLoaded=true;}catch(e){if(state.user?.uid===id){v31p2.error=message(e);v32.assignmentError=v31p2.error;v32.assignmentLoaded=false}}finally{v31p2.studentLoading=false;if(['student-assignments','home'].includes(state.view))render()}}
async function v31p2LoadSubmissions(id){if(ROLE!=='teacher')return;v31p2.openId=id;v31p2.loading=true;render();try{const x=await backend.request('teacher/assignments/submissions?id='+encodeURIComponent(id),{token:auth._token()});if(v31p2.openId===id)v31p2.submissions=x.items||[]}catch(e){v31p2.error=message(e)}finally{v31p2.loading=false;if(state.view==='teacher-assignments')render()}}
const v31p2Moderation={items:[],loading:false,error:''};
function v31p2AdminReviewUI(){return `${title('مراجعة واجبات المعلمين','لا يظهر واجب للطلاب حتى توافق الإدارة عليه')}
 ${v31p2Moderation.error?`<div class="v22-card" role="alert">${E(v31p2Moderation.error)}</div>`:''}
 <section class="v22-card">${v31p2Moderation.loading?'<p>جارٍ قراءة الواجبات...</p>':v31p2Moderation.items.length?v31p2Moderation.items.map(a=>`<article class="v31p2-item"><strong>${E(a.title||'واجب')}</strong><small>${E(a.subjectName||a.subject||'')} • ${E(stageNames[a.stage]||'')} • الصف ${E(a.grade||'')} • ${E(v31Date(a.dueAt))}</small><p>${E(a.instructions||'')}</p><div class="v22-btnrow">${B('اعتماد ونشر','v31p2-review','v22-primary',`data-id="${E(a.id)}" data-decision="approve"`)}${B('رفض','v31p2-review','v22-danger',`data-id="${E(a.id)}" data-decision="reject"`)}</div></article>`).join(''):empty('لا توجد واجبات قيد المراجعة','ستظهر طلبات المعلمين هنا عند إرسال واجبات جديدة.')}</section>`}
async function v31p2LoadAdminReview(){if(ROLE!=='admin'||!state.user)return;v31p2Moderation.loading=true;render();try{const x=await backend.request('admin/assignments/pending',{token:auth._token()});v31p2Moderation.items=x.items||[];v31p2Moderation.error=''}catch(e){v31p2Moderation.error=message(e)}finally{v31p2Moderation.loading=false;if(state.view==='assignment-review')render()}}
/* V26 — native live-API administration inside the V20 portal; no legacy page links. */
const V26_PANELS=new Set(['news','notifications','settings','subscriptions','schedule','live','community','communications','teacher-notifications','teacher-communications','teacher-live','support','subscription-requests']);
const v26={data:{},loading:false,error:'',requestId:0,edit:{},activeRoom:''};
const v26Read=async(path)=>await read(path);
const v26Rows=(key)=>rows(v26.data[key]||{}).sort((a,b)=>Number(b.createdAt||b.date||0)-Number(a.createdAt||a.date||0));
const v26When=(x)=>x?new Date(Number(x)).toLocaleDateString('ar-EG'):'';
const v26Select=(name,opts,sel='',emptyLabel='')=>`<label>${E(name)}<select name="${E(opts.key||'scope')}" ${opts.required?'required':''}>${emptyLabel?`<option value="">${E(emptyLabel)}</option>`:''}${opts.items.map(([v,t])=>`<option value="${E(v)}" ${String(v)===String(sel)?'selected':''}>${E(t)}</option>`).join('')}</select></label>`;
const v26Scope=(chosen={})=>{const t=chosen.type||'public',stage=chosen.stage||'primary',grade=String(chosen.grade||1),subs=subjectList(stage,grade,t);return `<div class="v26-scope"><label>التعليم<select name="type"><option value="public" ${t!=='azhar'?'selected':''}>التربية والتعليم</option><option value="azhar" ${t==='azhar'?'selected':''}>الأزهر</option></select></label><label>المرحلة<select name="stage">${Object.entries(stageNames).map(([k,n])=>`<option value="${k}" ${stage===k?'selected':''}>${E(n)}</option>`).join('')}</select></label><label>الصف<select name="grade">${Array.from({length:gradeNum[stage]||3},(_,i)=>`<option value="${i+1}" ${grade===String(i+1)?'selected':''}>${i+1}</option>`).join('')}</select></label><label>المادة<select name="subject" required>${subs.map(x=>`<option value="${E(x.id)}" ${x.id===chosen.subject?'selected':''}>${E(x.name)}</option>`).join('')}</select></label></div>`};
const v26RowsUI=(list,rowName,actions)=>list.length?list.map(x=>`<article class="v26-item"><div><strong>${E(x.title||x.name||'عنصر')}</strong><small>${E(rowName(x))}</small></div><div class="v26-actions">${actions(x)}</div></article>`).join(''):empty('لا يوجد محتوى حتى الآن','يمكنك إنشاء أول عنصر من النموذج الموجود هنا.');
function v26AdminNews(){const items=v26Rows('posts'),edit=items.find(x=>x.id===v26.edit.news)||{};return `${title('الأخبار والإعلانات','إضافة وتعديل الأخبار التي تظهر في واجهة الطلاب')}<div class="v22-two"><form id="v26-news-form" class="v22-card v22-form"><h3>${edit.id?'تعديل الخبر':'إضافة خبر'}</h3><label>العنوان<input name="title" maxlength="130" required value="${E(edit.title||'')}"></label><label>المحتوى<textarea name="content" required rows="5">${E(edit.content||'')}</textarea></label><label>رابط صورة (اختياري)<input name="image" type="url" value="${E(edit.image||'')}"></label><button class="v22-btn v22-primary">${edit.id?'حفظ الخبر':'نشر الخبر'}</button>${edit.id?B('إلغاء التعديل','v26-cancel-edit','v22-secondary','data-part="news"'):''}</form><section class="v22-card"><h3>الأخبار (${items.length})</h3>${v26RowsUI(items,x=>`${v26When(x.date)} • ${x.isHidden?'مخفي':'ظاهر'}`,x=>B('تعديل','v26-edit','v22-secondary',`data-part="news" data-id="${E(x.id)}"`)+B(x.isHidden?'إظهار':'إخفاء','v26-toggle','v22-secondary',`data-part="posts" data-id="${E(x.id)}" data-field="isHidden" data-current="${x.isHidden===true}"`))}</section></div>`}
function v26AdminNotifications(){const items=v26Rows('notificationBroadcasts');return `${title('الإشعارات الموجهة','إرسال إشعار حقيقي مع تحديد الفئة ومدة الصلاحية')}<div class="v22-two"><form id="v26-notice-form" class="v22-card v22-form"><h3>إرسال إشعار</h3><label>العنوان<input name="title" maxlength="100" required></label><label>نص الإشعار<textarea name="text" maxlength="900" required></textarea></label><div class="v26-scope"><label>التعليم<select name="type"><option value="">الكل</option><option value="public">عام</option><option value="azhar">أزهر</option></select></label><label>المرحلة<select name="stage"><option value="">الكل</option><option value="primary">ابتدائي</option><option value="prep">إعدادي</option><option value="sec">ثانوي</option></select></label><label>الصف (اختياري)<input name="grade" type="number" min="1" max="6"></label><label>الأولوية<select name="priority"><option value="normal">عادي</option><option value="high">مهم</option><option value="urgent">عاجل</option></select></label></div><label>مدة العرض بالأيام<input name="days" type="number" min="1" max="30" value="7" required></label><label>رابط داخلي اختياري<input name="href" placeholder="./lesson.html?..." maxlength="500"></label><button class="v22-btn v22-primary">نشر الإشعار</button></form><section class="v22-card"><h3>الإشعارات (${items.length})</h3>${v26RowsUI(items,x=>`${x.text||''} • ${x.isActive===false?'متوقف':'نشط'}`,x=>B(x.isActive===false?'تفعيل':'إيقاف','v26-toggle','v22-secondary',`data-part="notificationBroadcasts" data-id="${E(x.id)}" data-field="isActive" data-current="${x.isActive===false?'false':'true'}"`))}</section></div>`}
function v26AdminSettings(){const s=val(v26.data.settings);return `${title('الإعدادات','التحكم في اسم الأكاديمية وصور الأغلفة وروابطها الموجودة فعليًا في النظام')}<form id="v26-settings-form" class="v22-card v22-form v26-settings"><div class="v26-scope"><label>اسم الموقع<input name="siteName" required value="${E(s.siteName||'أكاديمية اجتاز')}"></label><label>بداية عنوان الصفحة الرئيسية<input name="publicHeroLead" maxlength="90" value="${E(s.publicHeroLead||'المذاكرة لها')}"></label><label>النص المميز في عنوان الرئيسية<input name="publicHeroHighlight" maxlength="90" value="${E(s.publicHeroHighlight||'شكل جديد.')}"></label><label>السطر الثاني في عنوان الرئيسية<input name="publicHeroEnd" maxlength="90" value="${E(s.publicHeroEnd||'رحلتك تبدأ هنا.')}"></label><label>رقم / رابط واتساب<input name="whatsapp" value="${E(s.whatsapp||'')}"></label><label>رابط الشعار<input name="siteLogo" value="${E(s.siteLogo||'')}"></label><label>غلاف قبل تسجيل الدخول<input name="publicHeroUrl" value="${E(s.publicHeroUrl||'')}"></label><label>غلاف تسجيل الدخول<input name="authVisualUrl" value="${E(s.authVisualUrl||'')}"></label><label>غلاف لوحة الطالب<input name="dashboardHeroUrl" value="${E(s.dashboardHeroUrl||'')}"></label><label>وصف غلاف الطالب<input name="dashboardHeroSubtitle" value="${E(s.dashboardHeroSubtitle||'')}"></label></div><label>نبذة عن الأكاديمية<textarea name="aboutText" rows="4">${E(s.aboutText||'')}</textarea></label><button class="v22-btn v22-primary">حفظ إعدادات الموقع</button><p class="v26-hint">سيجري تحديث مفاتيح الإعدادات الظاهرة فقط دون استبدال باقي إعدادات الموقع.</p></form>`}

function v30AppearanceUI(){
 const type=state.v30VisualType||'public',stage=state.v30VisualStage||'primary',grade=String(state.v30VisualGrade||1);
 const st=v30StageCover(type,stage),gr=v30GradeCover(type,stage,grade),parts=v30HomeSections(),hero=siteSettings();
 const stageList=Object.entries(stageNames).map(([id,name],i)=>{const meta=v30StageCover(type,id);return `<button class="v30-visual-picker ${id===stage?'active':''}" type="button" data-action="v30-choose-stage" data-stage="${id}"><img src="${E(safeURL(meta.imageUrl)||pic(['books.png','math.png','graduation.png'][i]))}" alt=""><span><strong>${E(name)}</strong><small>${meta.isHidden?'مخفية':'ظاهرة'}</small></span></button>`}).join('');
 const gradeList=Array.from({length:gradeNum[stage]},(_,i)=>{const id=String(i+1),meta=v30GradeCover(type,stage,id);return `<button class="v30-visual-picker ${id===grade?'active':''}" type="button" data-action="v30-choose-grade" data-grade="${id}"><img src="${E(safeURL(meta.imageUrl)||pic('graduation.png'))}" alt=""><span><strong>${gradeName(stage,id)}</strong><small>${meta.isHidden?'مخفي':'ظاهر'}</small></span></button>`}).join('');
 const homeParts=V30_HOME_PARTS.map(([id,label,defaultOrder])=>{const part=parts.find(x=>x.id===id);return `<div class="v30-home-row" data-v43-section="${id}"><div><strong>${E(label)}</strong><small>${id==='stages'?'يمكن للزائر الوصول للمراحل من القائمة حتى عند إخفاء القسم':'قسم الصفحة الرئيسية'}</small></div><div class="v43-move"><button type="button" data-action="v43-move" data-direction="up" data-section="${id}" aria-label="تحريك القسم لأعلى">↑</button><button type="button" data-action="v43-move" data-direction="down" data-section="${id}" aria-label="تحريك القسم لأسفل">↓</button></div><label>الترتيب<input type="number" name="order_${id}" min="0" max="9999" step="1" value="${part?.order??defaultOrder}" required></label><label class="v30-check"><input type="checkbox" name="show_${id}" ${part?.visible!==false?'checked':''}> إظهار القسم</label></div>`}).join('');
 return `${title('الصور وترتيب الصفحة الرئيسية','التحكم في صور المراحل والصفوف وترتيب أقسام الرئيسية دون تغيير روابط الدروس والاختبارات')}
 <div class="v22-card v30-appearance-head"><div><h3>نطاق الصور</h3><p>لكل نظام تعليمي صور مستقلة؛ التغييرات تظهر للطالب بعد تحديث البيانات.</p></div><label>نوع التعليم<select id="v30-visual-type"><option value="public" ${type==='public'?'selected':''}>التربية والتعليم</option><option value="azhar" ${type==='azhar'?'selected':''}>الأزهر الشريف</option></select></label></div>
 <div class="v30-appearance-grid"><section class="v22-card"><h3>أغلفة المراحل</h3><div class="v30-visual-list">${stageList}</div><form id="v30-stage-visual-form" class="v22-form v30-visual-form"><h4>تعديل ${E(stageNames[stage])}</h4><label>رابط الصورة<input type="url" name="imageUrl" value="${E(st.imageUrl||'')}" placeholder="https://example.com/stage.jpg"></label><label>وصف البطاقة<input name="subtitle" maxlength="110" value="${E(st.subtitle||'')}" placeholder="${gradeNum[stage]} صفوف دراسية"></label><label>ترتيب المرحلة<input type="number" name="order" min="0" max="9999" step="1" required value="${Number.isInteger(Number(st.order))&&st.order!==undefined?Number(st.order):(Object.keys(stageNames).indexOf(stage)+1)*10}"></label><label class="v30-check"><input type="checkbox" name="isHidden" ${st.isHidden?'checked':''}> إخفاء المرحلة عن الطلاب</label><button class="v22-btn v22-primary" type="submit">حفظ بيانات المرحلة</button></form></section>
 <section class="v22-card"><h3>أغلفة الصفوف — ${E(stageNames[stage])}</h3><div class="v30-visual-list">${gradeList}</div><form id="v30-grade-visual-form" class="v22-form v30-visual-form"><h4>تعديل ${gradeName(stage,grade)}</h4><label>رابط الصورة<input type="url" name="imageUrl" value="${E(gr.imageUrl||'')}" placeholder="https://example.com/grade.jpg"></label><label>وصف البطاقة<input name="subtitle" maxlength="110" value="${E(gr.subtitle||'')}" placeholder="المواد والدروس المخصصة لهذا الصف"></label><label>ترتيب الصف<input type="number" name="order" min="0" max="9999" step="1" required value="${Number.isInteger(Number(gr.order))&&gr.order!==undefined?Number(gr.order):Number(grade)*10}"></label><label class="v30-check"><input type="checkbox" name="isHidden" ${gr.isHidden?'checked':''}> إخفاء الصف عن الطلاب</label><button class="v22-btn v22-primary" type="submit">حفظ بيانات الصف</button></form></section></div>
 <section class="v22-card v30-home-editor"><div class="v30-section-head"><div><h3>أقسام الصفحة الرئيسية</h3><p>تحكم في ترتيب الأقسام وإظهارها، مع الحفاظ على بانر V20 وزر تسجيل الدخول.</p></div></div><form id="v30-home-layout-form" class="v22-form">${homeParts}<button class="v22-btn v22-primary" type="submit">حفظ ترتيب الرئيسية</button></form></section>
 <section class="v22-card"><h3>البانر الرئيسي</h3><p>عنوان البانر وصورته وشعار الأكاديمية تتحكم فيها بالفعل من قسم الإعدادات.</p>${B('تعديل بانر الرئيسية','route','v22-secondary','data-view="settings"')}</section>
 <div class="v30-appearance-grid v30-identity-grid"><section class="v22-card"><div class="v30-section-head"><div><h3>هوية الأكاديمية والنصوص العامة</h3><p>تغيير الكلمات الظاهرة أعلى الصفحات والتذييل وأزرار الرئيسية مع بقاء ألوان وشكل V20.</p></div></div>
 <form id="v30-brand-form" class="v22-form v30-visual-form"><label>الشعار النصي بجوار اسم الأكاديمية<input name="tagline" maxlength="90" required value="${E(v30Slogan())}"></label><label>وصف تذييل الصفحات<input name="footerText" maxlength="180" required value="${E(v30Footer())}"></label><label>زر البدء الرئيسي<input name="heroPrimaryLabel" maxlength="45" required value="${E(v30Brand().heroPrimaryLabel||'ابدأ التعلم الآن')}"></label><label>زر استكشاف المراحل<input name="heroSecondaryLabel" maxlength="45" required value="${E(v30Brand().heroSecondaryLabel||'تصفح المراحل')}"></label><button class="v22-btn v22-primary" type="submit">حفظ هوية الصفحات</button></form></section>
 <section class="v22-card"><div class="v30-section-head"><div><h3>روابط التواصل الرسمية</h3><p>اترك الرابط فارغًا لإخفاء المنصة؛ تظهر الروابط المحفوظة داخل الصفحة واللوحات دون إعادة رفع ملفات.</p></div></div>
 <form id="v30-social-form" class="v22-form v30-visual-form">${v30SocialPlatforms.map(([id,label])=>`<label>${E(label)}<input name="${id}" type="url" maxlength="500" placeholder="https://" value="${E(val(siteSettings().socialLinks)[id]||(id==='whatsapp'?v30HttpsURL(siteSettings().whatsapp):''))}"></label>`).join('')}<label class="v30-check"><input type="checkbox" name="hideSocialLinks" ${v30Brand().hideSocialLinks?'checked':''}> إخفاء جميع روابط التواصل مؤقتًا</label><button class="v22-btn v22-primary" type="submit">حفظ روابط التواصل</button><small>روابط HTTPS فقط. الروابط تفتح في تبويب جديد.</small></form></section></div>`;
}
function v26AdminSubscriptions(){const items=v26Rows('subscriptionPlansV1'),edit=items.find(x=>x.id===v26.edit.subscriptions)||{};return `${title('الاشتراكات والباقات','إنشاء الباقات وتعديلها دون مغادرة لوحة الإدارة')}<div class="v22-two"><form id="v26-plan-form" class="v22-card v22-form"><h3>${edit.id?'تعديل الباقة':'باقة جديدة'}</h3><label>اسم الباقة<input name="name" required value="${E(edit.name||'')}"></label><div class="v26-scope"><label>السعر بالجنيه<input name="price" type="number" step="0.01" min="0" required value="${Number(edit.price||0)}"></label><label>المدة بالأيام<input name="durationDays" type="number" min="1" max="365" required value="${Number(edit.durationDays||30)}"></label><label>طريقة الوصول<select name="accessMode"><option value="all" ${edit.accessMode!=='subjects'?'selected':''}>كل المواد</option><option value="subjects" ${edit.accessMode==='subjects'?'selected':''}>مواد محددة — تتطلب ضبطًا متقدمًا</option></select></label></div><label>الوصف<textarea name="description">${E(edit.description||'')}</textarea></label><label class="v26-checkbox"><input name="isActive" type="checkbox" ${edit.isActive===false?'':'checked'}> الباقة متاحة</label><button class="v22-btn v22-primary">${edit.id?'حفظ التعديل':'إنشاء باقة'}</button>${edit.id?B('إلغاء','v26-cancel-edit','v22-secondary','data-part="subscriptions"'):''}<p class="v26-hint">هذا النموذج يدعم باقات جميع المواد فقط؛ استخدم وضع جميع المواد قبل الحفظ، وسيُستكمل تخصيص المواد لاحقًا.</p></form><section class="v22-card"><h3>الباقات (${items.length})</h3>${v26RowsUI(items,x=>`${Number(x.price||0)} جنيه • ${x.durationDays||30} يوم • ${x.isActive===false?'موقوفة':'متاحة'}`,x=>B('تعديل','v26-edit','v22-secondary',`data-part="subscriptions" data-id="${E(x.id)}"`)+B(x.isActive===false?'تفعيل':'إيقاف','v26-toggle','v22-secondary',`data-part="subscriptionPlansV1" data-id="${E(x.id)}" data-field="isActive" data-current="${x.isActive===false?'false':'true'}"`))}</section></div>`}
function v26AdminSchedule(){const items=v26Rows('scheduleEvents'),edit=items.find(x=>x.id===v26.edit.schedule)||{};const days=['الأحد','الإثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت'];return `${title('جدول الحصص','إنشاء المواعيد الأسبوعية الحقيقية وربطها بالصفوف والمواد')}<div class="v22-two"><form id="v26-schedule-form" class="v22-card v22-form"><h3>${edit.id?'تعديل الحصة':'إضافة حصة أسبوعية'}</h3><label>العنوان<input name="title" required value="${E(edit.title||'')}"></label><label>اسم المعلم<input name="teacher" value="${E(edit.teacher||'')}"></label>${v26Scope(edit)}<div class="v26-scope"><label>اليوم<select name="dayOfWeek">${days.map((d,i)=>`<option value="${i}" ${Number(edit.dayOfWeek||0)===i?'selected':''}>${d}</option>`).join('')}</select></label><label>الوقت<input type="time" name="time" required value="${E(edit.time||'18:00')}"></label><label>المدة بالدقائق<input name="duration" type="number" min="10" max="360" value="${Number(edit.duration||60)}" required></label></div><label>رابط الحصة<input name="url" type="url" value="${E(edit.url||'')}"></label><label class="v26-checkbox"><input type="checkbox" name="isActive" ${edit.isActive===false?'':'checked'}> الحصة نشطة</label><button class="v22-btn v22-primary">${edit.id?'حفظ التعديل':'إضافة الحصة'}</button>${edit.id?B('إلغاء','v26-cancel-edit','v22-secondary','data-part="schedule"'):''}</form><section class="v22-card"><h3>الحصص (${items.length})</h3>${v26RowsUI(items,x=>`${days[Number(x.dayOfWeek)||0]} ${x.time||''} • ${x.teacher||''} • ${x.isActive===false?'موقوفة':'نشطة'}`,x=>B('تعديل','v26-edit','v22-secondary',`data-part="schedule" data-id="${E(x.id)}"`)+B(x.isActive===false?'تفعيل':'إيقاف','v26-toggle','v22-secondary',`data-part="scheduleEvents" data-id="${E(x.id)}" data-field="isActive" data-current="${x.isActive===false?'false':'true'}"`))}</section></div>`}
function v26AdminLive(){const items=v26Rows('liveSessions'),edit=items.find(x=>x.id===v26.edit.live)||{};return `${title('البث المباشر','إدارة مواعيد البث وروابط المشاهدة ضمن تصميم V20')}<div class="v22-two"><form id="v26-live-form" class="v22-card v22-form"><h3>${edit.id?'تعديل البث':'جلسة جديدة'}</h3><label>عنوان الجلسة<input name="title" required value="${E(edit.title||'')}"></label><label>المعلم<input name="teacher" value="${E(edit.teacher||'')}"></label>${v26Scope(edit)}<div class="v26-scope"><label>حالة البث<select name="status"><option value="upcoming">قادم</option><option value="live" ${edit.status==='live'?'selected':''}>مباشر الآن</option><option value="ended" ${edit.status==='ended'?'selected':''}>منتهٍ</option></select></label><label>الموعد<input name="scheduledTime" type="datetime-local" required value="${edit.scheduledTime?new Date(Number(edit.scheduledTime)-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16):''}"></label><label>المدة بالدقائق<input name="duration" type="number" min="10" max="360" value="${Number(edit.duration||60)}"></label></div><label>رابط يوتيوب<input name="youtubeLiveUrl" type="url" value="${E(edit.youtubeLiveUrl||'')}"></label><label>رابط الاجتماع<input name="zoomLink" type="url" value="${E(edit.zoomLink||'')}"></label><label class="v26-checkbox"><input name="isFree" type="checkbox" ${edit.isFree?'checked':''}> مجاني</label><button class="v22-btn v22-primary">${edit.id?'حفظ التعديل':'إضافة البث'}</button>${edit.id?B('إلغاء','v26-cancel-edit','v22-secondary','data-part="live"'):''}</form><section class="v22-card"><h3>الجلسات (${items.length})</h3>${v26RowsUI(items,x=>`${v26When(x.scheduledTime)} • ${x.teacher||''} • ${x.status||'upcoming'}`,x=>B('تعديل','v26-edit','v22-secondary',`data-part="live" data-id="${E(x.id)}"`))}</section></div>`}
function v26AdminCommunity(){const entries=v26Rows('community').slice(0,60);return `${title('المجتمع التعليمي','عرض أحدث منشورات المجتمع داخل لوحة الإدارة الجديدة')}<div class="v22-card"><h3>بيانات المجتمع</h3>${entries.length?entries.map(x=>`<article class="v26-item"><div><strong>${E(x.title||x.name||x.id)}</strong><small>المنشورات والمجموعات محفوظة في فروع المجتمع الحالية.</small></div></article>`).join(''):empty('لا توجد بيانات مجتمع بعد','يمكن للطلاب إنشاء المنشورات داخل النظام عندما يكون القسم متاحًا.')}<p class="v26-hint">لم تُنقل أدوات البلاغات والموافقة التفصيلية بعد؛ لن نُجري قرارات إشرافية من قائمة مجمّعة غير مكتملة.</p></div>`}
function v26AdminCommunications(){const raw=val(v26.data.communicationSubmissionsV1),entries=Object.entries(raw).flatMap(([uid,items])=>rows(items).map(x=>({...x,uid}))).sort((a,b)=>Number(b.createdAt||0)-Number(a.createdAt||0)).slice(0,60);return `${title('التواصل والمراجعات','متابعة رسائل وطلبات التواصل المرسلة من المعلمين والطلاب')}<div class="v22-card"><h3>آخر الطلبات (${entries.length})</h3>${entries.length?entries.map(x=>`<article class="v26-item"><div><strong>${E(x.title||x.kind||'رسالة')}</strong><small>${E((x.text||'').slice(0,220))}</small><small>الحالة: ${E(x.status||'pending')} • ${v26When(x.createdAt)}</small></div></article>`).join(''):empty('لا توجد طلبات','ستظهر هنا الطلبات المرسلة للمراجعة.')}<p class="v26-hint">عرض الطلبات متصل بالبيانات الفعلية. اعتماد الرسائل وتوجيهها يحتاج مسار المعالجة الكامل ولذلك لم أضف زر موافقة غير آمن.</p></div>`}
function v26TeacherNotifications(){const items=v26Rows('notificationBroadcasts').filter(x=>x.isActive!==false&&(!x.expiresAt||x.expiresAt>Date.now())).slice(0,50);return `${title('الإشعارات','التنبيهات المعلنة على مستوى الأكاديمية')}<section class="v22-card"><h3>التنبيهات الحالية</h3>${items.length?items.map(x=>`<article class="v26-item"><div><strong>${E(x.title||'تنبيه')}</strong><small>${E(x.text||'')}</small><small>${v26When(x.createdAt)}</small></div></article>`).join(''):empty('لا توجد إشعارات','لم تُرسل إشعارات عامة حتى الآن.')}</section>`}
