function v29DiagnosticsUI(){
 const d=state.v29Diagnostics||{},counts=val(d.counts),checks=val(d.checks);
 const loading=state.v29DiagLoading;
 const line=(label,value,bad=false)=>`<div class="v22-card" style="padding:18px"><div class="v22-muted">${E(label)}</div><strong style="font-size:30px">${Number(value)||0}</strong>${bad&&Number(value)>0?'<div style="color:#b34427;font-size:12px">بحاجة إلى مراجعة</div>':''}</div>`;
 const issues=Number(checks.orphanQuizzes||0)+Number(checks.emptyQuizzes||0);
 return `${title('فحص ربط البيانات','تقرير آمن للمدير فقط، يُقرأ مباشرة من قاعدة بيانات الأكاديمية.')}
 <div class="v22-btnrow">${B(loading?'جارٍ التحديث...':'تحديث الفحص','v29-diagnostics-refresh','v22-primary',loading?'disabled':'')}</div>
 ${state.v29DiagError?`<div class="v22-card" role="alert">تعذر تحميل الفحص: ${E(state.v29DiagError)}</div>`:''}
 ${!d.ok?empty(loading?'جارٍ فحص البيانات':'لم يتم تشغيل الفحص بعد','اضغط على «تحديث الفحص» لجلب ملخص جديد من الخادم.'):`
 <div class="v22-stats">${line('الدروس',counts.lessons)}${line('الاختبارات المنفصلة',counts.quizzes)}${line('ملفات المكتبة',counts.files)}${line('حسابات الطلاب التجريبية',counts.students)}${line('ملفات المعلمين',counts.teacherProfiles)}${line('طلبات المعلمين المعلقة',counts.pendingTeacherSubmissions)}</div>
 <h3>سلامة الربط</h3><div class="v22-stats">${line('اختبارات مرتبطة بدروس غير موجودة',checks.orphanQuizzes,true)}${line('اختبارات بلا أسئلة',checks.emptyQuizzes,true)}${line('دروس بأسئلة مدمجة',checks.lessonsWithEmbeddedQuestions)}${line('دروس دون فيديو مباشر',checks.lessonsWithoutDirectVideo)}${line('طلاب لهم تقدم قديم',checks.studentsWithLegacyMastery)}${line('طلاب لهم نتائج اختبارات جديدة',checks.studentsWithNewQuizResults)}</div>
 <div class="v22-card"><strong>${issues?'هناك روابط تستحق المراجعة':'لم يظهر في هذه الفحوص خطأ ربط واضح'}</strong><p>هذا فحص لتناسق البيانات، وليس اختبارًا لتسجيل الدخول أو للحفظ المباشر. تقدم الطالب القديم لا يُحسب تلقائيًا نتيجة اختبار. وقد يكون الدرس بلا فيديو مباشر لكنه يحتوي على فيديو معلم منفصل.</p><small>آخر قراءة: ${E(d.generatedAt||'غير معروف')}</small></div>`}`;
}
