function m1Date(v){const d=new Date(String(v||'').replace(' ','T')+'Z');return Number.isNaN(+d)?'—':d.toLocaleString('ar-EG',{dateStyle:'medium',timeStyle:'short'});}
function m1Errors(err){m1.error=message(err);showtoast('تعذر تحميل قسم المنافسات: '+m1.error);}
async function m1Load(view=state.view){if(!state.user||!m1Views.includes(view))return;m1.loading=true;m1.error='';try{
 if(view==='m1-virtual'){m1.virtual=(await m1Api('m1/virtual')).items||[];}
 if(view==='m1-challenges'||view==='m1-quiz'){m1.items=(await m1Api('m1/challenges')).items||[];}
 if(view==='m1-leaderboard'){const x=await m1Api('m3/leaderboard',{mode:m3.mode,period:m3.period,subject:m3.subject});m1.leaderboard=x.items||[];m3.board=x;}
 if(view==='m1-points'){const x=await m1Api('m1/points');m1.balance=x.points||0;m3.history=(await m1Api('m3/history')).items||[];}
 if(view==='m1-challenges'){if(ROLE==='student')m3.history=(await m1Api('m3/history')).items||[];else if(['admin','teacher'].includes(ROLE))m3.overview=await m1Api('m3/overview');}
 }catch(err){m1Errors(err)}finally{m1.loading=false;if(state.view===view)render()}}
function m1Heading(t,desc){return `${title(t,desc)}${m1.error?`<div class="m1-alert" role="alert">${E(m1.error)} — تأكد من تشغيل ملف SQL الخاص بـ M1.</div>`:''}`;}
function m3HistoryUI(){return `<section class="v22-card m3-history"><h3>مشاركاتي الأخيرة</h3><p>كل محاولة هنا محفوظة على الخادم، وليست نقاط محاكاة.</p>${m3.history.length?m3.history.map(r=>`<article class="m3-history-row"><div><strong>${E(r.title)}</strong><small>${E(r.subject)} · ${Number(r.is_training)===1?'تدريبي':'رسمي'} · ${E(m1Date(r.created_at))}</small></div><div class="m3-history-result"><b>${E(r.percentage)}%</b><span>+${E(r.points_awarded)} نقطة</span></div></article>`).join(''):empty('لا توجد مشاركات محفوظة','ابدأ أول تحدٍ لتظهر نتائجه هنا.')}</section>`;}
function m3StudentOverview(){const count=m3.history.length;const points=m3.history.reduce((n,x)=>n+Number(x.points_awarded||0),0);return `<div class="m3-info-strip"><span>🎯 <b>${count}</b> مشاركات</span><span>💎 <b>${points}</b> نقطة من هذه المحاولات</span>${B('سجل مشاركاتي','route','v22-secondary','data-view="m1-points"')}</div>`;}
function m3StaffOverview(){const a=m3.overview;if(!a)return '';const st=a.summary||{};return `<section class="m3-admin-summary"><h3>نظرة سريعة على التحديات</h3><div class="m3-admin-metrics">${[['التحديات المعروضة',st.all||0],['بانتظار الموافقة',st.pending||0],['منشورة',st.published||0],['محاولات الطلاب',st.attempts||0]].map(([label,n])=>`<div><span>${label}</span><strong>${n}</strong></div>`).join('')}</div><details><summary>تفاصيل المشاركة والنتائج</summary>${(a.items||[]).length?`<div class="m3-report-rows">${a.items.map(x=>`<div><strong>${E(x.title)}</strong><small>${x.isTraining?'تدريبي':'رسمي'} · ${E(x.subject)} · ${x.attempts} محاولة</small><b>${x.average===null?'—':E(x.average)+'%'} متوسط</b></div>`).join('')}</div>`:empty('لا توجد تحديات بعد','أنشئ أول تحدٍ لعرض إحصاءاته.')}</details></section>`;}
function m1Choices(scope={}){return `<div class="m1-fields"><label>نظام التعليم<select name="educationType" required><option value="public" ${scope.type==='public'?'selected':''}>التربية والتعليم</option><option value="azhar" ${scope.type==='azhar'?'selected':''}>الأزهر الشريف</option></select></label><label>المرحلة<select name="stage" required>${[['primary','ابتدائي'],['prep','إعدادي'],['sec','ثانوي']].map(([v,n])=>`<option value="${v}" ${scope.stage===v?'selected':''}>${n}</option>`).join('')}</select></label><label>الصف<select name="grade" required>${[1,2,3,4,5,6].map(g=>`<option value="${g}" ${String(scope.grade)===String(g)?'selected':''}>${g}</option>`).join('')}</select></label></div>`;}
