<div class="m1-dashboard-grid"><div class="m1-tile"><span>المنافسون</span><strong>${m1.virtual.length}</strong></div><div class="m1-tile"><span>نشطون</span><strong>${m1.virtual.filter(v=>Number(v.is_active)===1).length}</strong></div><div class="m1-tile"><span>حسابات دخول للمنافسين</span><strong>0</strong></div></div>
