function v51ReportView(){return `${title('التقرير التعليمي المفصل','عرض بيانات الطالب الحقيقية من الخادم مع الحفاظ على صلاحيات الوصول.')}${v51ReportPanel()}`;}
async function v51Load(view=state.view){if(!state.user)return;v51.error='';v51.loading=true;try{
 if(ROLE==='student'&&view==='v51-guardians'){const data=await backend.request('v51/student/guardians',{token:auth._token()});v51.guardians=data.guardians||[];}
 if(ROLE==='parent'&&view==='v51-contact'){const data=await backend.request('v51/parent/links',{token:auth._token()});v51.links=data.links||[];v51.phone=data.phone||'';}
 if(ROLE==='admin'&&view==='v51-contacts'){await v51LoadContacts();}
 }catch(err){v51.error=message(err)}finally{v51.loading=false;if(state.view===view)render()}}
async function v51LoadContacts(){const data=await backend.request('v51/admin/contacts',{token:auth._token(),query:v51.filter});v51.contacts=data.contacts||[];if(data.limited)v51.error='تم بلوغ حد 2000 سجل؛ ضيّق نطاق البحث قبل التصدير.';}
async function v51LoadReport(studentId){if(!studentId||!state.user)return;const owner=state.user.uid;v51.reportId=studentId;v51.report=null;v51.reportBusy=true;v51.error='';v53.reportId=studentId;v53.recipients=[];v53.loading=ROLE==='admin';v53.error='';render();try{const data=await backend.request('v51/report',{token:auth._token(),query:{studentId}});if(state.user?.uid===owner&&v51.reportId===studentId)v51.report=data.report||null;
 if(ROLE==='admin'&&state.user?.uid===owner&&v51.reportId===studentId){try{const target=await backend.request('v53/report/recipients',{token:auth._token(),query:{studentId}});if(state.user?.uid===owner&&v51.reportId===studentId)v53.recipients=target.recipients||[];}catch(err){if(state.user?.uid===owner&&v51.reportId===studentId)v53.error=message(err);}}
 }catch(e){v51.error=message(e)}finally{if(state.user?.uid===owner&&v51.reportId===studentId){v51.reportBusy=false;v53.loading=false;render()}}}
async function v51Submit(form){const fd=new FormData(form),f=k=>String(fd.get(k)||'').trim();
 if(form.id==='v51-export-form'){v51.filter={educationType:f('educationType'),stage:f('stage'),grade:f('grade')};v51.contacts=[];await v51LoadContacts();return render()}
 if(form.classList.contains('v51-contact-form')){const sid=form.dataset.student,phone=f('phone'),optIn=fd.has('optIn');await post('v51/parent/contact-consent',{studentId:sid,phone,optIn});showtoast('تم حفظ رغبتك في التواصل');return v51Load('v51-contact')}
}
function v51CsvEscape(raw,isPhone=false){let x=String(raw??'');if(isPhone&&x)x="'"+x;else if(/^[\s]*[=+\-@]/.test(x))x="'"+x;return '"'+x.replace(/"/g,'""')+'"';}
function v51DownloadContacts(){const head=['الطالب','هاتف ولي الأمر','نوع التعليم','المرحلة','الصف'];let csv='\uFEFF'+head.map(x=>v51CsvEscape(x)).join(',')+'\r\n';for(const r of v51.contacts)csv+=[v51CsvEscape(r.studentName),v51CsvEscape(r.parentPhone,true),v51CsvEscape(r.educationType),v51CsvEscape(r.stage),v51CsvEscape(r.grade)].join(',')+'\r\n';const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='egtaz-v51-opt-in-parents.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2500);showtoast('تم تنزيل قائمة موافقات التواصل فقط');}
function v51ReportMessage(r){return `تقرير أكاديمية اجتاز — ${r.student?.name||'الطالب'}\nالدروس المكتملة: ${r.lessons?.completed||0}\nعدد الاختبارات: ${r.quizzes?.count||0}\nمتوسط الاختبارات: ${r.quizzes?.average==null?'لا توجد درجات':r.quizzes.average+'%'}\nالواجبات المصححة: ${r.homework?.graded||0}\nالحضور المسجل: ${r.attendance?.present||0}\nيرجى الدخول إلى حساب ولي الأمر على الأكاديمية لمتابعة التقرير الكامل.\nhttps://academy.egtaz.online/parent.html`;}
function v51WhatsApp(){const r=v51.report;if(!r)return;
 if(!confirm('ستفتح واتساب برسالة تحتوي على ملخص دراسي شخصي. تأكد من هوية المستلم واضغط إرسال بنفسك. متابعة؟'))return;
 window.open('https://wa.me/?text='+encodeURIComponent(v51ReportMessage(r)),'_blank','noopener,noreferrer');}
async function v53WhatsApp(){if(ROLE!=='admin'||!v51.report||v53.reportId!==v51.report.student?.id||v53.loading)return;
 const sid=v51.report.student.id,userId=state.user?.uid;const pid=document.getElementById('v53-parent-select')?.value||'';
 const recipient=v53.recipients.find(x=>x.parentId===pid);if(!recipient)throw Error('اختر ولي أمر مصرحًا له أولًا');
 if(!confirm('ستفتح محادثة '+recipient.name+' ('+recipient.maskedPhone+') برسالة التقرير. لن يتم الإرسال تلقائيًا. متابعة؟'))return;
 // Open synchronously on the click, before the awaited permission check (popup blockers).
 const tab=window.open('about:blank','_blank');if(tab)tab.opener=null;
 try{const response=await post('v53/report/whatsapp-target',{studentId:sid,parentId:pid});
   if(ROLE!=='admin'||state.user?.uid!==userId||v51.report?.student?.id!==sid)throw Error('تم تغيير التقرير، أعد المحاولة');
   const phone=String(response.phone||'');if(!/^201[0125][0-9]{8}$/.test(phone))throw Error('رقم ولي الأمر غير صالح');
   const url='https://wa.me/'+phone+'?text='+encodeURIComponent(v51ReportMessage(v51.report));
   if(tab&&!tab.closed){tab.location.href=url;}else{window.location.assign(url);}
 }catch(err){if(tab&&!tab.closed)tab.close();throw err;}}

async function v51Click(el){const action=el.dataset.action,id=el.dataset.id;
 if(action==='v51-refresh')return v51Load(state.view);
 if(action==='v51-student-consent'){if(ROLE!=='student')return;const allow=el.dataset.allow==='true';await post('v51/student/guardian/contact-consent',{parentId:id,allow});showtoast('تم تعديل موافقة التواصل');return v51Load('v51-guardians')}
 if(action==='v51-revoke'){if(ROLE!=='student'||!confirm('فك ارتباط ولي الأمر سيمنع وصوله إلى تقاريرك فورًا. هل تريد المتابعة؟'))return;await post('v51/student/guardian/revoke',{parentId:id});showtoast('تم إلغاء ارتباط ولي الأمر');return v51Load('v51-guardians')}
 if(action==='v51-report-refresh'){const sid=ROLE==='parent'?(state.kid||v33ChildIds()[0]):ROLE==='student'?state.user.uid:v51.reportId;if(sid)return v51LoadReport(sid)}
 if(action==='v51-admin-report'){if(ROLE!=='admin')return;v51.reportId=id;goto('v51-report');return v51LoadReport(id)}
 if(action==='v51-direct-whatsapp')return v53WhatsApp();
 if(action==='v51-share-report')return v51WhatsApp();
 if(action==='v51-export-download'){if(ROLE!=='admin'||!confirm('تصدير أرقام المصرح لهم فقط؟ احتفظ بالملف في مكان آمن.'))return;v51.contacts=[];await v51LoadContacts();if(v51.contacts.length)return v51DownloadContacts();showtoast('لا توجد سجلات مصرح بها حاليًا');return;}
}

