// V28: reconcile saved data with the server. This backend does not push changes;
// an explicit read is needed to update an already-open student/teacher/admin tab.
let v28SyncRunning=null;
let v28LastSync=0;
let v28PendingPaint=false;
let v28Channel=null;
try{if('BroadcastChannel' in window)v28Channel=new BroadcastChannel('egtaz-v28-changes')}catch{}
function v28AnnounceUpdate(){try{v28Channel?.postMessage({kind:'changed',at:Date.now()})}catch{}}
const v28HasUnsavedForm=()=>Boolean(APP.querySelector('form[data-v28-dirty="1"]'));
const v28ShouldDefer=()=>busy||v28HasUnsavedForm()||Boolean(APP.contains(document.activeElement)&&document.activeElement?.matches?.('input,textarea,select,[contenteditable="true"]'));
function v28SafePaint(){if(v28ShouldDefer()){v28PendingPaint=true;return}v28PendingPaint=false;render()}
async function v28Sync(force=false){
 if(!state.ready||state.loading||(!force&&document.hidden))return;
 if(v28SyncRunning){
   // A manual refresh must not report the previous in-flight background read as fresh.
   if(force){await v28SyncRunning.catch(()=>{});return v28Sync(true)}
   return v28SyncRunning;
 }
 if(!force&&Date.now()-v28LastSync<12000)return;
 const userId=state.user?.uid;
 v28SyncRunning=(async()=>{
  const names=['customSubjects','lessons','quizzes','settings','files','posts'];
  const extra=ROLE==='student'&&userId?[`studentProfilesV3/${userId}`,`learningV4/mastery/${userId}`,`learningV4/resume/${userId}`,`learningV4/favorites/${userId}`,`learningV4/reviews/${userId}/v32`]:
    ROLE==='teacher'&&userId?[`teacherProfiles/${userId}`,`teacherSubmissions/${userId}`]:
    ROLE==='admin'?[`teacherProfiles`,'teacherSubmissions',...(state.view==='students-legacy'?['studentProfilesV3']:[])]:
    ROLE==='parent'&&userId?[`parentLinksV4/${userId}`]:[];
  const results=await Promise.allSettled([...names,...extra].map(read));
  // A logout/login during a network request must never apply another account's data.
  if((state.user?.uid||null)!==(userId||null))return;
  let changed=false,good=0;
  for(let i=0;i<results.length;i++){
    if(results[i].status!=='fulfilled')continue;
    good++;
    const v=results[i].value;
    if(i<names.length){const key=names[i];if(JSON.stringify(val(state.public[key]))!==JSON.stringify(val(v))){state.public[key]=val(v);changed=true}}
    else if(userId===state.user?.uid||ROLE==='admin'){
      const route=extra[i-names.length];
      const setChanged=(key,value)=>{if(JSON.stringify(val(state[key]))!==JSON.stringify(val(value))){state[key]=val(value);changed=true}};
      if(ROLE==='student'){
        if(route===`studentProfilesV3/${userId}`){setChanged('profile',v);if(state.profile?.name&&state.user)state.user.displayName=state.profile.name;}
        else if(route===`learningV4/mastery/${userId}`)setChanged('legacyMastery',v);else if(route===`learningV4/resume/${userId}`){if(JSON.stringify(v32.resume)!==JSON.stringify(val(v))){v32.resume=val(v);changed=true}}else if(route===`learningV4/favorites/${userId}`){if(JSON.stringify(v32.favorites)!==JSON.stringify(val(v))){v32.favorites=val(v);changed=true}}else if(route===`learningV4/reviews/${userId}/v32`){if(JSON.stringify(v32.reviews)!==JSON.stringify(val(v))){v32.reviews=val(v);changed=true}};
      }else if(ROLE==='teacher'){
        if(route===`teacherProfiles/${userId}`)setChanged('teacherProfile',v);
        else if(route===`teacherSubmissions/${userId}`&&JSON.stringify(val(state.liveData.mySubmissions))!==JSON.stringify(val(v))){state.liveData.mySubmissions=val(v);changed=true;}
      }else if(ROLE==='admin'){
        if(route==='teacherProfiles'&&JSON.stringify(val(state.liveData.adminTeachers))!==JSON.stringify(val(v))){state.liveData.adminTeachers=val(v);changed=true;}
        else if(route==='teacherSubmissions'){
          const submissions=Object.entries(val(v)).flatMap(([tid,items])=>rows(items).map(x=>({...x,teacherId:tid}))).sort((a,b)=>Number(b.createdAt||0)-Number(a.createdAt||0));
          if(JSON.stringify(state.liveData.adminSubmissions||[])!==JSON.stringify(submissions)){state.liveData.adminSubmissions=submissions;changed=true;}
        }else if(route==='studentProfilesV3'&&JSON.stringify(val(state.liveData.adminStudents))!==JSON.stringify(val(v))){state.liveData.adminStudents=val(v);changed=true;}
      }else if(ROLE==='parent'&&route===`parentLinksV4/${userId}`){if(JSON.stringify(val(state.linked))!==JSON.stringify(val(v))){state.linked=val(v);changed=true;}}
    }

  }
  if(ROLE==='teacher'&&userId&&good===results.length){
    try{const mine=await backend.request('teacher/content/list',{token:auth._token()});if(state.user?.uid===userId&&JSON.stringify(val(state.liveData.myContent))!==JSON.stringify(val(mine.items))){state.liveData.myContent=val(mine.items);changed=true;}}
    catch(err){if(force)throw new Error('تعذر تحديث المحتوى المنشور للمعلم: '+message(err));}
  }
  if(ROLE==='parent'&&userId&&good===results.length){
    const ids=rows(state.linked).map(x=>x.studentId||x.id).filter(Boolean);
    const loads=await Promise.allSettled(ids.flatMap(id=>[read('studentProfilesV3/'+id),read('learningV4/mastery/'+id)]));
    if(force&&ids.some((_,j)=>loads[2*j]?.status==='rejected'))throw Error('تعذر تحديث بيانات أحد الأبناء من الخادم');
    const kids={},mastery={};
    ids.forEach((id,j)=>{kids[id]=loads[2*j]?.status==='fulfilled'?loads[2*j].value:state.kids[id]||{};mastery[id]=loads[2*j+1]?.status==='fulfilled'?loads[2*j+1].value:state.kidsMastery[id]||{};});
    if(JSON.stringify(val(state.kids))!==JSON.stringify(val(kids))){state.kids=kids;changed=true;}
    if(JSON.stringify(val(state.kidsMastery))!==JSON.stringify(val(mastery))){state.kidsMastery=mastery;changed=true;}
  }
  if(force&&good!==results.length)throw Error('تعذر جلب بعض التحديثات من الخادم، تأكد من الاتصال وصلاحيات الحساب');
  if(changed)v28SafePaint();
  v28LastSync=Date.now();
 })().finally(()=>{v28SyncRunning=null});
 return v28SyncRunning;
}
